/* ── VERITAS Question Bank · 165 questions ── */
window.VERITAS_QUESTIONS = [

  // ════════════════════════════════════════════
  // GOVERNANCE (q001–q008, q098–q102, q166–q176)
  // ════════════════════════════════════════════
  { id: 'q001', text: 'Cadre deployment by political parties to state positions should be banned.', theme: 'Governance', weight: 1.5, contextShort: 'The Zondo Commission strongly condemned cadre deployment as a core enabler of State Capture.', contextLong: 'Cadre deployment refers to the practice of appointing individuals to key government, SOE, and institutional positions based primarily on their loyalty to a political party rather than on merit. The Zondo Commission found it allowed corruption to flourish. Proponents argue it ensures transformation; critics say it breeds incompetence and graft. This question asks whether you believe this practice should be legally prohibited.', axes: { stateAuthority: 0.8, constitutionalLiberalism: -0.9, transformation: -0.4 } },
  { id: 'q002', text: 'The President should be directly elected by the people, not by Parliament.', theme: 'Governance', weight: 1.2, contextShort: 'South Africa uses a parliamentary system where the legislature elects the President.', contextLong: 'Currently, voters choose a party, and the National Assembly elects the President. A direct election would give the President an independent popular mandate, potentially strengthening accountability. Critics warn it could lead to populist authoritarianism and weaken parliamentary oversight. This debate touches on the structure of SA\'s post-apartheid constitutional compromise.', axes: { constitutionalLiberalism: -0.3, stateAuthority: 0.5, secularDemocracy: 0.3 } },
  { id: 'q003', text: 'Coalition governments are better for South Africa than single-party dominance.', theme: 'Governance', weight: 1.0, contextShort: 'The ANC lost its parliamentary majority in 2024, leading to a Government of National Unity.', contextLong: 'For the first time since 1994, SA entered an era of formal national coalition governance. Single-party dominance often bred arrogance and corruption; coalitions force negotiation and power-sharing but can be unstable. This question probes whether you believe the messy bargaining of coalitions is healthier than the stability of a single dominant party.', axes: { constitutionalLiberalism: 0.4, stateAuthority: -0.3, stability: -0.2 } },
  { id: 'q004', text: 'Provincial governments should be abolished to reduce costs.', theme: 'Governance', weight: 0.8, contextShort: 'South Africa has nine provinces, each with its own legislature and executive.', contextLong: 'The nine provincial governments were established in 1994 to balance regional interests. Critics say they duplicate national functions and waste resources. Abolishing them could save billions; opponents argue it would centralise power in Pretoria and undermine the federal compromise.', axes: { stateAuthority: 0.5, constitutionalLiberalism: -0.4, stability: 0.2 } },
  { id: 'q005', text: 'Chapter 9 institutions (Public Protector, HRC) should have binding enforcement powers.', theme: 'Governance', weight: 1.1, contextShort: 'Chapter 9 institutions currently make recommendations, not binding orders.', contextLong: 'The Constitution established the Public Protector, SAHRC, and other Chapter 9 bodies as independent watchdogs. However, their findings are often ignored. Giving them binding enforcement power would strengthen accountability but could upset separation of powers. This question probes your tolerance for judicial-style oversight versus executive discretion.', axes: { constitutionalLiberalism: 0.6, stateAuthority: -0.4, libertarian: 0.3 } },
  { id: 'q006', text: 'The electoral threshold for parliamentary representation should be raised.', theme: 'Governance', weight: 0.7, contextShort: 'South Africa has no electoral threshold — any party with enough votes for one seat enters Parliament.', contextLong: 'The absence of a threshold means tiny parties can gain seats, fostering pluralism but also parliamentary fragmentation. Raising the threshold would reduce micro-parties and stabilise governance, but would silence minority and regional voices. This pits democratic inclusivity against governability.', axes: { stability: 0.5, constitutionalLiberalism: -0.2, stateAuthority: 0.3 } },
  { id: 'q007', text: 'Members of the executive should be barred from holding party leadership positions simultaneously.', theme: 'Governance', weight: 1.0, contextShort: 'Cabinet ministers often simultaneously hold top party positions, blurring state and party lines.', contextLong: 'In SA, the President is both head of state and head of the majority party. Cabinet ministers often sit on the ANC\'s NEC. This fusion can cause conflicts of interest. Separating them would align with stricter separation-of-powers models but could weaken party discipline.', axes: { constitutionalLiberalism: 0.7, stateAuthority: -0.6, secularDemocracy: 0.4 } },
  { id: 'q008', text: 'Traditional leaders should have formal legislative authority in rural areas.', theme: 'Governance', weight: 1.2, contextShort: 'The Constitution recognises traditional leadership but subjects it to democratic law.', contextLong: 'Traditional leaders hold significant de facto authority in areas like KwaZulu-Natal. Giving them formal legislative power would entrench a non-elected, often patriarchal parallel governance system. Supporters argue it respects cultural heritage and deepens local governance. This question directly engages the tension between traditional authority and secular democracy.', axes: { traditionalAuthority: 0.9, secularDemocracy: -0.8, transformation: -0.3 } },
  { id: 'q098', text: 'South Africa should adopt a mixed electoral system combining constituencies and proportional representation.', theme: 'Governance', weight: 0.9, contextShort: 'SA currently uses a pure proportional representation system without constituencies.', contextLong: 'A mixed system would give voters direct constituency representatives, potentially improving accountability. Critics say it would weaken party cohesion. This probes electoral reform preferences.', axes: { constitutionalLiberalism: 0.3, stateAuthority: -0.2, stability: 0.4 } },
  { id: 'q099', text: 'The Deputy President should be elected separately from the President.', theme: 'Governance', weight: 0.8, contextShort: 'Currently, the President appoints the Deputy President from among members of the National Assembly.', contextLong: 'A separately elected Deputy would have an independent mandate, potentially balancing presidential power. Opponents argue it could create two competing centres of power and destabilise the executive. This tests your view on executive unity versus checks and balances.', axes: { constitutionalLiberalism: 0.4, stateAuthority: -0.3, stability: -0.2 } },
  { id: 'q100', text: 'Municipal managers should be elected rather than appointed.', theme: 'Governance', weight: 0.7, contextShort: 'Municipal managers are currently appointed by municipal councils, often leading to political interference.', contextLong: 'Direct election of municipal managers would give them a popular mandate and reduce cadre deployment at local level. Critics warn it could politicise administration further and reduce professional expertise. This tests your preference for democratic control versus professional bureaucracy.', axes: { libertarian: 0.4, constitutionalLiberalism: 0.3, stateAuthority: -0.3 } },
  { id: 'q101', text: 'The size of the National Assembly should be reduced from 400 to 250 seats.', theme: 'Governance', weight: 0.8, contextShort: 'South Africa has one of the largest parliaments relative to population among democracies.', contextLong: 'Reducing the size would cut costs and streamline decision-making. Opponents say it would reduce representativeness, especially for smaller parties and minorities. This pits fiscal prudence against democratic inclusivity.', axes: { stability: 0.4, constitutionalLiberalism: -0.2, economicRight: 0.3 } },
  { id: 'q102', text: 'The Speaker of Parliament should be elected by secret ballot.', theme: 'Governance', weight: 0.9, contextShort: 'The Speaker is currently elected by open vote, which can subject the decision to party discipline.', contextLong: 'A secret ballot would free MPs to vote for the most impartial candidate, strengthening parliamentary independence. Critics say it undermines party accountability and could produce an unpredictable outcome. This question tests your commitment to parliamentary sovereignty versus party control.', axes: { constitutionalLiberalism: 0.5, stateAuthority: -0.4, libertarian: 0.3 } },
  { id: 'q166', text: 'The state should fund political party campaigns to reduce private influence.', theme: 'Governance', weight: 0.8, contextShort: 'Currently, parties rely on private donations, which can create obligations to funders.', contextLong: 'Public funding would level the playing field and reduce corruption. Critics say it would entrench existing parties and use taxpayer money for political purposes. This tests campaign finance reform.', axes: { constitutionalLiberalism: 0.3, stateAuthority: 0.2, economicLeft: 0.2 } },
  { id: 'q167', text: 'South Africa should introduce compulsory voting.', theme: 'Governance', weight: 0.9, contextShort: 'Voter turnout has been declining, from over 80% in 1999 to under 60% in 2024.', contextLong: 'Compulsory voting would ensure high turnout and greater legitimacy. Critics say it infringes on individual freedom and forces the disengaged to vote. This probes the balance between civic duty and personal liberty.', axes: { authoritarian: 0.4, libertarian: -0.5, stability: 0.4 } },
  { id: 'q169', text: 'MPs should be subject to recall by their constituencies between elections.', theme: 'Governance', weight: 1.0, contextShort: 'SA\'s proportional representation system means MPs are accountable to parties, not voters.', contextLong: 'A recall mechanism would give voters direct leverage over MPs who fail to represent them. Critics argue it would undermine party discipline and expose MPs to organised campaigns by well-funded interest groups. This tests direct democracy versus representative stability.', axes: { constitutionalLiberalism: 0.5, libertarian: 0.4, stateAuthority: -0.3, stability: -0.2 } },
  { id: 'q170', text: 'The Presidency should be limited to a single five-year term.', theme: 'Governance', weight: 1.0, contextShort: 'Currently the President may serve two five-year terms.', contextLong: 'A single-term limit would reduce the incentive for incumbents to abuse power for re-election. Critics say it deprives the country of continuity and experienced leadership. This tests your preference for turnover versus experience.', axes: { constitutionalLiberalism: 0.4, stateAuthority: -0.3, stability: -0.2 } },
  { id: 'q171', text: 'Parliament should have the power to subpoena private citizens for public inquiries.', theme: 'Governance', weight: 0.8, contextShort: 'Parliamentary committees have limited coercive powers to compel testimony from non-officials.', contextLong: 'Giving Parliament subpoena power would strengthen accountability over corporate actors and civil society. Opponents say it could be abused for political witch-hunts and infringes on individual rights. This tests the reach of parliamentary oversight.', axes: { stateAuthority: 0.5, constitutionalLiberalism: -0.3, authoritarian: 0.3 } },
  { id: 'q172', text: 'All senior government appointments should require parliamentary confirmation.', theme: 'Governance', weight: 1.0, contextShort: 'Many senior appointments — including SOE boards — are made by the President with limited parliamentary input.', contextLong: 'Confirmation hearings would expose unsuitable candidates and reduce cronyism. Critics argue it would slow government and give opposition parties a veto over executive choices. This is a fundamental checks-and-balances question.', axes: { constitutionalLiberalism: 0.6, stateAuthority: -0.5, stability: -0.2 } },
  { id: 'q173', text: 'A national referendum should be required before any constitutional amendment.', theme: 'Governance', weight: 1.1, contextShort: 'Currently, constitutional amendments require only a two-thirds parliamentary majority.', contextLong: 'A referendum would ensure the public has a direct say on fundamental changes. Critics say it opens the process to demagoguery, is expensive, and could block necessary reform. This tests representative versus direct democracy.', axes: { libertarian: 0.5, constitutionalLiberalism: 0.3, stateAuthority: -0.4, stability: -0.3 } },
  { id: 'q174', text: 'Political parties that incite ethnic division should be banned.', theme: 'Governance', weight: 1.2, contextShort: 'Section 19 of the Constitution guarantees the right to form and participate in political parties.', contextLong: 'Banning parties that exploit ethnicity could protect social cohesion. Critics argue it gives the ruling party an instrument to silence minority voices and is incompatible with free political competition. This tests tolerance versus cohesion.', axes: { authoritarian: 0.5, stateAuthority: 0.4, constitutionalLiberalism: -0.4, libertarian: -0.5 } },
  { id: 'q175', text: 'Public servants convicted of corruption should forfeit their pension.', theme: 'Governance', weight: 1.1, contextShort: 'Currently, convicted officials often retain pension benefits even after imprisonment.', contextLong: 'Forfeiture would deter corruption and recover some of the public money lost. Critics argue it amounts to double punishment and could leave families destitute. This tests proportionality versus deterrence.', axes: { authoritarian: 0.4, constitutionalLiberalism: -0.3, stability: 0.4, transformation: 0.3 } },
  { id: 'q176', text: 'South Africa should adopt an anti-floor-crossing law preventing MPs from changing parties.', theme: 'Governance', weight: 0.9, contextShort: 'Floor crossing was banned nationally but allowed in some other legislative contexts.', contextLong: 'A strict ban would give voters certainty that their party vote is binding on elected representatives. Opponents argue it traps MPs in parties they can no longer support and inhibits coalition flexibility. This tests voter mandate versus legislative independence.', axes: { stability: 0.4, constitutionalLiberalism: 0.2, libertarian: -0.3, stateAuthority: 0.2 } },

  // ════════════════════════════════════════════
  // LAND & PROPERTY (q009–q016, q103–q105, q177–q181)
  // ════════════════════════════════════════════
  { id: 'q009', text: 'Land expropriation without compensation should be accelerated.', theme: 'Land & Property', weight: 1.4, contextShort: 'Section 25 of the Constitution remains a contested clause.', contextLong: 'Colonial and apartheid eras systematically dispossessed black South Africans of land. Section 25 requires just and equitable compensation for expropriation. Amending it to allow nil compensation is a rallying cry for the EFF and some ANC factions. Proponents say it\'s essential for justice; opponents warn it could undermine property rights and investment.', axes: { transformation: 0.9, racialRedress: 0.8, economicLeft: 0.6, westernAlignment: -0.5 } },
  { id: 'q010', text: 'The Ingonyama Trust should be abolished.', theme: 'Land & Property', weight: 1.3, contextShort: 'The Trust controls 2.8 million hectares of land in KwaZulu-Natal under the Zulu monarch.', contextLong: 'Established just before the 1994 transition, the Ingonyama Trust holds vast tracts of traditional land under the Zulu king. Critics say it perpetuates feudal control and prevents individual ownership. Defenders, including the IFP and Zulu royal house, see it as a vital cultural institution protecting communal land. Abolishing it would fundamentally reshape land governance in KZN.', axes: { traditionalAuthority: -0.9, secularDemocracy: 0.8, transformation: 0.5, racialRedress: 0.4 } },
  { id: 'q011', text: 'Foreign nationals should be allowed to own agricultural land in South Africa.', theme: 'Land & Property', weight: 0.9, contextShort: 'Currently, there are few restrictions on foreign land ownership beyond general investment regulations.', contextLong: 'Restricting foreign ownership is common in many countries to protect domestic agriculture. Supporters of open ownership cite investment and economic growth. This question probes your attitude toward external influence on a sensitive national resource.', axes: { westernAlignment: 0.5, panAfrican: -0.3, economicRight: 0.4 } },
  { id: 'q012', text: 'Communal land tenure systems should be converted to individual freehold title.', theme: 'Land & Property', weight: 1.1, contextShort: 'Millions of South Africans live on communal land governed by traditional authorities or the state.', contextLong: 'Freehold title gives individuals ownership and collateral. Communal tenure preserves collective identity but can limit economic mobility. This pits individual property rights against communal cultural traditions.', axes: { individualRights: 0.6, traditionalAuthority: -0.7, economicRight: 0.5, ubuntuCollectivism: -0.5 } },
  { id: 'q013', text: 'The state should have first right of refusal on all land sales.', theme: 'Land & Property', weight: 1.0, contextShort: 'A pre-emptive right would allow the state to match any private offer for land.', contextLong: 'This would accelerate land reform but could distort the property market and deter investment. It\'s a direct intervention tool that tests the balance between state authority and market freedom.', axes: { stateAuthority: 0.7, economicLeft: 0.6, transformation: 0.5, economicRight: -0.5 } },
  { id: 'q014', text: 'Farm dwellers should have permanent tenure rights regardless of ownership.', theme: 'Land & Property', weight: 1.2, contextShort: 'Millions of farm dwellers face eviction with limited legal protection.', contextLong: 'The Extension of Security of Tenure Act provides some protection but is poorly enforced. Strengthening it pits human rights against property rights and addresses a legacy of dispossession and exploitation on commercial farms.', axes: { transformation: 0.6, racialRedress: 0.7, individualRights: 0.5, economicRight: -0.4 } },
  { id: 'q015', text: 'Urban land should be subject to the same expropriation laws as rural land.', theme: 'Land & Property', weight: 0.8, contextShort: 'Land reform debate often focuses on farmland, but urban land inequality is severe.', contextLong: 'Including urban land in expropriation frameworks would address spatial apartheid but could destabilise city property markets. This question asks whether you believe the urgency of spatial justice outweighs market stability.', axes: { transformation: 0.7, racialRedress: 0.6, economicLeft: 0.5, stability: -0.4 } },
  { id: 'q016', text: 'The Land Court should have power to set land value independently of market price.', theme: 'Land & Property', weight: 1.0, contextShort: 'Land value for redistribution is usually determined by market price or negotiation.', contextLong: 'An independent valuation mechanism could speed up land reform but might be seen as arbitrary and unconstitutional. This pits state-driven transformation against the constitutional protection of property.', axes: { stateAuthority: 0.6, constitutionalLiberalism: -0.5, transformation: 0.5, economicLeft: 0.4 } },
  { id: 'q103', text: 'Land reform beneficiaries should be allowed to sell their land freely after receiving it.', theme: 'Land & Property', weight: 1.0, contextShort: 'Some land reform programmes restrict beneficiaries from selling land for a period.', contextLong: 'Allowing free sale would give beneficiaries full ownership rights and the ability to use land as collateral. Restriction is meant to prevent quick dispossession but limits economic agency.', axes: { individualRights: 0.6, economicRight: 0.5, transformation: -0.2 } },
  { id: 'q104', text: 'Mining rights should be subject to community consent on communal land.', theme: 'Land & Property', weight: 1.2, contextShort: 'Communities on communal land often have limited say over mining activities.', contextLong: 'Requiring community consent would empower rural communities and align with free, prior and informed consent principles. Critics argue it could deter mining investment and deprive the state of strategic resource control.', axes: { ubuntuCollectivism: 0.7, transformation: 0.6, traditionalAuthority: 0.4, economicRight: -0.5 } },
  { id: 'q105', text: 'The 1913 Natives Land Act should be formally repudiated and its effects reversed.', theme: 'Land & Property', weight: 1.3, contextShort: 'The 1913 Act allocated only 7% of land to the black majority.', contextLong: 'Formal repudiation would be a symbolic and legal acknowledgment of historic injustice, potentially opening the door to land claims beyond what Section 25 allows. Critics argue it would create legal chaos and undermine the constitutional settlement.', axes: { transformation: 0.8, racialRedress: 0.9, constitutionalLiberalism: -0.5 } },
  { id: 'q177', text: 'Backyard dwellers should receive formal recognition and services from municipalities.', theme: 'Land & Property', weight: 1.0, contextShort: 'Millions of South Africans rent informal backyard rooms, largely invisible to the state.', contextLong: 'Formal recognition would improve living conditions and help municipalities plan services. Landlords fear it could undermine their property rights. This touches on the boundary between informal and formal housing markets.', axes: { transformation: 0.6, economicLeft: 0.5, stateAuthority: 0.3, economicRight: -0.3 } },
  { id: 'q178', text: 'Land that lies fallow for more than five years should revert to the state.', theme: 'Land & Property', weight: 1.1, contextShort: 'Significant portions of redistributed and privately owned land lie unused.', contextLong: 'A "use it or lose it" policy could accelerate productive land use and reform. Critics say it violates property rights and creates uncertainty. This tests state intervention in land management.', axes: { stateAuthority: 0.6, transformation: 0.7, economicLeft: 0.5, economicRight: -0.5 } },
  { id: 'q179', text: 'The state should build high-density social housing in wealthy suburbs, not just townships.', theme: 'Land & Property', weight: 1.3, contextShort: 'The apartheid spatial pattern persists in South African cities.', contextLong: 'Building social housing in affluent areas would directly dismantle spatial apartheid and reduce commuting costs. Wealthy communities often resist such developments. This tests spatial justice versus property values.', axes: { transformation: 0.8, racialRedress: 0.7, economicLeft: 0.6, economicRight: -0.5 } },

  // ════════════════════════════════════════════
  // ECONOMY & MARKETS (q017–q024, q106–q109, q162, q168, q182–q189)
  // ════════════════════════════════════════════
  { id: 'q017', text: 'Basic income grant of R350/month should be made permanent and increased.', theme: 'Economy & Markets', weight: 1.1, contextShort: 'The SRD grant introduced during COVID is temporary, renewed annually.', contextLong: 'A universal basic income grant would be a massive fiscal commitment. Proponents say it reduces extreme poverty; critics question affordability and work disincentives. This goes to the heart of the welfare state vs. market self-reliance debate.', axes: { economicLeft: 0.7, transformation: 0.5, ubuntuCollectivism: 0.6, individualRights: -0.3 } },
  { id: 'q018', text: 'The South African Reserve Bank should be nationalised and its mandate expanded.', theme: 'Economy & Markets', weight: 1.2, contextShort: 'The SARB is privately owned by shareholders but operates with constitutional independence.', contextLong: 'Nationalising the SARB and adding employment to its mandate would align it with developmental goals. Critics say it would undermine monetary stability and investor confidence. This question examines your stance on central bank independence.', axes: { economicLeft: 0.8, transformation: 0.6, westernAlignment: -0.5, economicRight: -0.7 } },
  { id: 'q019', text: 'Black Economic Empowerment (BEE) should be replaced with needs-based empowerment.', theme: 'Economy & Markets', weight: 1.3, contextShort: 'BEE uses racial classifications to distribute economic benefits.', contextLong: 'Critics say BEE benefits a politically connected elite and should be replaced by class-based redistribution. Defenders say it is essential for racial redress. This question forces a choice between race-based and class-based transformation.', axes: { nonRacialism: 0.7, racialRedress: -0.6, economicLeft: 0.3, transformation: -0.2 } },
  { id: 'q020', text: 'All state-owned enterprises (Eskom, Transnet, SAA) should be privatised.', theme: 'Economy & Markets', weight: 1.4, contextShort: 'SOEs have accumulated massive debt and operational failures.', contextLong: 'Privatisation could improve efficiency and reduce fiscal burden. Opponents fear job losses and loss of state control over strategic assets. This is the classic SOE reform dilemma.', axes: { economicRight: 0.9, economicLeft: -0.8, stateAuthority: -0.6, transformation: -0.5 } },
  { id: 'q021', text: 'The national minimum wage should be doubled.', theme: 'Economy & Markets', weight: 1.1, contextShort: 'The minimum wage is currently R27.58 per hour (2024).', contextLong: 'Doubling would significantly impact low-wage sectors. Labour unions support it; business warns of job losses. This question tests your tolerance for bold, pro-worker intervention vs. market caution.', axes: { economicLeft: 0.8, transformation: 0.5, stability: -0.4 } },
  { id: 'q022', text: 'South Africa should implement a wealth tax on net assets above R50 million.', theme: 'Economy & Markets', weight: 1.0, contextShort: 'South Africa has one of the highest Gini coefficients in the world.', contextLong: 'A wealth tax would directly address inequality but could trigger capital flight and is difficult to administer. This probes your preference for radical redistribution vs. investor-friendly stability.', axes: { economicLeft: 0.7, transformation: 0.6, economicRight: -0.6, westernAlignment: -0.3 } },
  { id: 'q023', text: 'Foreign companies should be required to have majority South African ownership.', theme: 'Economy & Markets', weight: 1.2, contextShort: 'Many African countries require local ownership in key sectors.', contextLong: 'Local ownership requirements would domesticate profits but could deter foreign investment. This tests your economic nationalism vs. openness to global capital.', axes: { economicLeft: 0.5, panAfrican: 0.6, westernAlignment: -0.5, transformation: 0.4 } },
  { id: 'q024', text: 'Cryptocurrency should be recognised as legal tender in South Africa.', theme: 'Economy & Markets', weight: 0.7, contextShort: 'The SARB currently regulates crypto as a financial asset, not currency.', contextLong: 'Adopting crypto could modernise the financial system but poses risks to monetary policy. This probes your openness to radical financial innovation vs. state control of currency.', axes: { economicRight: 0.6, libertarian: 0.5, stateAuthority: -0.4, westernAlignment: 0.4 } },
  { id: 'q106', text: 'South Africa should introduce a universal basic income grant of R1,500 per month.', theme: 'Economy & Markets', weight: 1.2, contextShort: 'Proposals for a universal basic income grant have gained traction.', contextLong: 'A universal grant would provide a permanent safety net and stimulate local economies, but at a huge fiscal cost. Critics argue it would create dependency and reduce the incentive to work.', axes: { economicLeft: 0.8, transformation: 0.6, ubuntuCollectivism: 0.7, economicRight: -0.7 } },
  { id: 'q107', text: 'The government should subsidise electric vehicle purchases to accelerate adoption.', theme: 'Economy & Markets', weight: 0.7, contextShort: 'Electric vehicle uptake is low in SA, constrained by cost and infrastructure.', contextLong: 'Subsidies could jump-start the green transition but are costly and may benefit wealthier buyers more. This tests your willingness to use public funds for environmental goals and industrial policy.', axes: { economicLeft: 0.4, transformation: 0.3, westernAlignment: 0.2 } },
  { id: 'q108', text: 'All South Africans should receive a share of mining profits through a sovereign wealth fund.', theme: 'Economy & Markets', weight: 1.1, contextShort: 'Countries like Norway and Botswana use sovereign wealth funds to share resource wealth with citizens.', contextLong: 'A South African fund would collect mining royalties and invest them for public benefit, potentially providing a dividend to all citizens. Critics say it requires massive administrative capacity and could be plundered.', axes: { economicLeft: 0.7, transformation: 0.5, stateAuthority: 0.5, westernAlignment: -0.2 } },
  { id: 'q109', text: 'The Johannesburg Stock Exchange should be required to prioritise local companies over foreign listings.', theme: 'Economy & Markets', weight: 0.8, contextShort: 'The JSE is one of the world\'s top 20 exchanges but many large companies are foreign-owned.', contextLong: 'Prioritising local listings would deepen domestic ownership of the economy. Critics say it would reduce the JSE\'s international competitiveness and limit capital flows.', axes: { panAfrican: 0.5, economicLeft: 0.4, westernAlignment: -0.4 } },
  { id: 'q162', text: 'South Africa should ban the export of unprocessed minerals.', theme: 'Economy & Markets', weight: 1.0, contextShort: 'SA exports raw minerals and imports beneficiated products, losing potential value.', contextLong: 'A ban would force local processing, creating jobs and industrial capacity. Critics say it would provoke trade disputes and require massive investment in processing plants.', axes: { economicLeft: 0.6, panAfrican: 0.4, westernAlignment: -0.5 } },
  { id: 'q168', text: 'The death of a breadwinner should automatically trigger state support for dependents.', theme: 'Economy & Markets', weight: 0.8, contextShort: 'Social grants exist for children and the elderly, but there is no automatic survivor grant.', contextLong: 'Automatic support would prevent families from falling into poverty after a breadwinner dies. Critics say it would be open to abuse and fiscally unsustainable. This tests the reach of the social safety net.', axes: { economicLeft: 0.7, ubuntuCollectivism: 0.6, stateAuthority: 0.4 } },
  { id: 'q182', text: 'The government should cap executive salaries at 10x the lowest-paid employee in an organisation.', theme: 'Economy & Markets', weight: 1.0, contextShort: 'South Africa has some of the highest pay ratios between executives and workers globally.', contextLong: 'A pay ratio cap would compress inequality and incentivise firms to raise the floor. Critics say it would drive talent abroad and distort compensation markets.', axes: { economicLeft: 0.7, transformation: 0.5, economicRight: -0.6, westernAlignment: -0.3 } },
  { id: 'q183', text: 'The informal economy should be brought fully into the formal tax net.', theme: 'Economy & Markets', weight: 0.9, contextShort: 'The informal economy accounts for an estimated 6% of GDP but contributes minimally to tax revenue.', contextLong: 'Formalisation would expand the tax base and provide workers with social protections. Critics argue it would crush survivalist businesses that cannot afford compliance costs.', axes: { economicRight: 0.3, stateAuthority: 0.4, economicLeft: -0.2, transformation: 0.2 } },
  { id: 'q184', text: 'South Africa should implement a four-year national development plan with binding targets.', theme: 'Economy & Markets', weight: 0.9, contextShort: 'The National Development Plan 2030 exists but is largely aspirational and poorly implemented.', contextLong: 'Binding targets would force accountability and coordinate investment. Critics warn that rigid targets distort priorities and cannot adapt to changing circumstances.', axes: { stateAuthority: 0.5, economicLeft: 0.4, stability: 0.4, economicRight: -0.3 } },
  { id: 'q185', text: 'South Africa should withdraw from the World Trade Organisation.', theme: 'Economy & Markets', weight: 0.8, contextShort: 'WTO rules constrain SA\'s ability to use tariffs and industrial subsidies.', contextLong: 'Withdrawal would restore policy space for industrialisation but could trigger retaliatory tariffs and collapse export markets. This is a radical trade sovereignty position.', axes: { panAfrican: 0.5, economicLeft: 0.6, westernAlignment: -0.7, stability: -0.5 } },
  { id: 'q186', text: 'State tenders above R10 million should be publicly advertised and awarded through open auction.', theme: 'Economy & Markets', weight: 1.1, contextShort: 'Procurement corruption costs SA an estimated R70 billion per year.', contextLong: 'Open auctions would reduce bid-rigging and preference for politically connected firms. Critics argue public procurement needs evaluation criteria beyond price.', axes: { constitutionalLiberalism: 0.5, economicRight: 0.4, transformation: -0.2, stability: 0.4 } },
  { id: 'q187', text: 'A state bank should be created to provide affordable credit to SMMEs.', theme: 'Economy & Markets', weight: 1.0, contextShort: 'Commercial banks rarely lend to small businesses without collateral or credit history.', contextLong: 'A state bank could close the financing gap for entrepreneurs. Critics say state banks accumulate non-performing loans and become captured by political interests.', axes: { economicLeft: 0.6, stateAuthority: 0.5, transformation: 0.5, economicRight: -0.4 } },
  { id: 'q188', text: 'South Africa should impose a sugar tax to combat obesity and diabetes.', theme: 'Economy & Markets', weight: 0.7, contextShort: 'A Health Promotion Levy on sugary beverages already exists but applies only to drinks.', contextLong: 'Extending it to all sugary foods would improve public health but would disproportionately affect poorer consumers. This tests paternalistic health policy versus regressive taxation.', axes: { authoritarian: 0.3, stateAuthority: 0.3, libertarian: -0.3, economicLeft: -0.2 } },
  { id: 'q189', text: 'Large retailers should be required to source a minimum percentage of goods locally.', theme: 'Economy & Markets', weight: 0.9, contextShort: 'Local procurement requirements in some sectors exist but are unevenly enforced.', contextLong: 'Minimum local sourcing would support domestic manufacturers and jobs. Critics argue it raises consumer prices and may violate trade agreements.', axes: { economicLeft: 0.5, panAfrican: 0.4, westernAlignment: -0.4, economicRight: -0.3 } },

  // ════════════════════════════════════════════
  // SOCIAL & RIGHTS (q025–q030, q110–q112, q190–q195)
  // ════════════════════════════════════════════
  { id: 'q025', text: 'Same-sex marriage should remain constitutionally protected.', theme: 'Social & Rights', weight: 1.2, contextShort: 'SA was the first country to prohibit discrimination based on sexual orientation in its Constitution.', contextLong: 'The Civil Union Act 2006 legalised same-sex marriage. Despite strong constitutional protection, social and religious opposition persists. This question tests your commitment to individual rights vs. traditional values.', axes: { libertarian: 0.8, traditionalAuthority: -0.7, secularDemocracy: 0.5, individualRights: 0.6 } },
  { id: 'q026', text: 'Abortion should be available on demand without gestational limits.', theme: 'Social & Rights', weight: 1.1, contextShort: 'SA law allows abortion on request up to 12 weeks, and under certain conditions thereafter.', contextLong: 'The Choice on Termination of Pregnancy Act is among Africa\'s most liberal. Expanding it further touches on bodily autonomy, religious ethics, and gender rights.', axes: { libertarian: 0.6, traditionalAuthority: -0.5, individualRights: 0.7, secularDemocracy: 0.4 } },
  { id: 'q027', text: 'Hate speech laws should criminalise speech that causes emotional harm.', theme: 'Social & Rights', weight: 1.0, contextShort: 'Current hate speech law requires intent to incite harm.', contextLong: 'Broadening hate speech to include emotional harm could protect vulnerable groups but risks chilling free expression. This is a classic liberty vs. protection debate.', axes: { authoritarian: 0.5, libertarian: -0.6, individualRights: -0.4, stateAuthority: 0.3 } },
  { id: 'q028', text: 'Sex work should be fully decriminalised.', theme: 'Social & Rights', weight: 0.9, contextShort: 'Sex work is currently criminalised in South Africa.', contextLong: 'Decriminalisation is supported by health organisations as harm reduction. Opponents cite moral and trafficking concerns. This tests your approach to personal autonomy and regulated vice.', axes: { libertarian: 0.7, individualRights: 0.6, traditionalAuthority: -0.5, secularDemocracy: 0.4 } },
  { id: 'q029', text: 'Religious organisations should pay tax on commercial activities.', theme: 'Social & Rights', weight: 0.8, contextShort: 'Churches and religious bodies are exempt from income tax on religious activities.', contextLong: 'Taxing commercial arms would level the playing field but could be seen as targeting religion. This probes the separation of church and commerce.', axes: { secularDemocracy: 0.6, traditionalAuthority: -0.5, economicLeft: 0.3, authoritarian: 0.2 } },
  { id: 'q030', text: 'The death penalty should be reinstated for certain violent crimes.', theme: 'Social & Rights', weight: 1.0, contextShort: 'Capital punishment was abolished by the Constitutional Court in 1995.', contextLong: 'Public frustration with violent crime has renewed debate. The Constitution prohibits cruel, inhuman or degrading punishment. This directly pits state violence against individual rights.', axes: { authoritarian: 0.8, libertarian: -0.9, constitutionalLiberalism: -0.7, westernAlignment: 0.3 } },
  { id: 'q110', text: 'Hate crimes should carry mandatory minimum sentences.', theme: 'Social & Rights', weight: 1.0, contextShort: 'Hate crimes legislation exists but sentencing discretion remains wide.', contextLong: 'Mandatory minimums would send a strong signal against discrimination, but remove judicial discretion and could lead to disproportionate punishment.', axes: { authoritarian: 0.5, libertarian: -0.4, stateAuthority: 0.3 } },
  { id: 'q111', text: 'Polygamous marriages should be fully recognised in civil law.', theme: 'Social & Rights', weight: 0.8, contextShort: 'Customary marriages, including polygamy, are recognised but civil marriage remains monogamous.', contextLong: 'Full recognition would extend legal protections to all spouses and respect cultural practices. Critics argue it could undermine gender equality and create complex inheritance issues.', axes: { traditionalAuthority: 0.6, secularDemocracy: -0.5, individualRights: 0.3, authoritarian: -0.2 } },
  { id: 'q112', text: 'The ban on smoking in public places should be extended to include e-cigarettes and vaping.', theme: 'Social & Rights', weight: 0.6, contextShort: 'Current tobacco legislation does not uniformly cover vaping products.', contextLong: 'Extending the ban would protect non-smokers from second-hand vapour and discourage youth uptake. Opponents say e-cigarettes help smokers quit and their risks are lower.', axes: { authoritarian: 0.3, libertarian: -0.3, stateAuthority: 0.2 } },
  { id: 'q190', text: 'Cannabis should be fully legalised and taxed, not merely decriminalised for private use.', theme: 'Social & Rights', weight: 1.0, contextShort: 'The Constitutional Court decriminalised private cannabis use in 2018, but a commercial market does not exist legally.', contextLong: 'Full legalisation would create a regulated market, generate tax revenue, and disrupt criminal networks. Critics fear normalisation of drug use and harms to youth.', axes: { libertarian: 0.7, secularDemocracy: 0.4, individualRights: 0.5, traditionalAuthority: -0.4 } },
  { id: 'q191', text: 'Conversion therapy targeting LGBTQ+ individuals should be criminalised.', theme: 'Social & Rights', weight: 1.1, contextShort: 'Conversion therapy is practised by some religious and medical practitioners in South Africa.', contextLong: 'Criminalisation would protect LGBTQ+ people from harmful pseudo-science. Religious practitioners argue it infringes on freedom of religion and counselling.', axes: { libertarian: 0.6, secularDemocracy: 0.5, traditionalAuthority: -0.6, individualRights: 0.6 } },
  { id: 'q192', text: 'The state should provide free legal name and gender marker changes for transgender individuals.', theme: 'Social & Rights', weight: 0.9, contextShort: 'The current process for legal gender recognition is lengthy, costly, and requires medical evidence.', contextLong: 'Simplifying and funding the process would affirm transgender rights and reduce administrative barriers. Critics argue it could be abused and requires safeguards.', axes: { libertarian: 0.6, individualRights: 0.7, traditionalAuthority: -0.5, economicLeft: 0.3 } },
  { id: 'q193', text: 'The state should restrict the advertising of junk food targeted at children.', theme: 'Social & Rights', weight: 0.7, contextShort: 'Childhood obesity is rising rapidly in South Africa.', contextLong: 'Restricting advertising would protect children from manipulative marketing. Critics say it is the responsibility of parents and would damage the advertising industry.', axes: { authoritarian: 0.3, stateAuthority: 0.3, libertarian: -0.3, economicLeft: 0.2 } },
  { id: 'q194', text: 'No one should be imprisoned solely for inability to pay a fine.', theme: 'Social & Rights', weight: 1.0, contextShort: 'Imprisonment for unpaid fines disproportionately affects the poor.', contextLong: 'Ending imprisonment for fine default would address class-based criminalisation. Critics argue it removes the deterrent for non-payment.', axes: { libertarian: 0.5, economicLeft: 0.5, constitutionalLiberalism: 0.4, authoritarian: -0.4 } },
  { id: 'q195', text: 'Racial slurs should be automatically classified as criminal hate speech.', theme: 'Social & Rights', weight: 1.1, contextShort: 'The Equality Court handles hate speech but automatic criminalisation would shift this to criminal courts.', contextLong: 'Criminal sanctions would signal the gravity of racial abuse. Critics argue the definition of slur is contested and automatic criminalisation chills speech and floods the criminal justice system.', axes: { authoritarian: 0.4, stateAuthority: 0.4, libertarian: -0.5, racialRedress: 0.5 } },

  // ════════════════════════════════════════════
  // SECURITY & JUSTICE (q031–q035, q113–q115, q196–q201)
  // ════════════════════════════════════════════
  { id: 'q031', text: 'Police should have the power to use lethal force against suspected violent criminals.', theme: 'Security & Justice', weight: 1.3, contextShort: 'Section 49 of the Criminal Procedure Act regulates the use of lethal force for arrest.', contextLong: 'Expanding lethal force powers could reduce violent crime but risks extrajudicial killings and echoes apartheid-era abuses. This probes your tolerance for hardline policing vs. human rights protections.', axes: { authoritarian: 0.7, libertarian: -0.8, stateAuthority: 0.6, constitutionalLiberalism: -0.5 } },
  { id: 'q032', text: 'South Africa should reintroduce a specialised Scorpions-style anti-corruption unit.', theme: 'Security & Justice', weight: 1.2, contextShort: 'The Scorpions were disbanded in 2009; the Hawks replaced them with less independence.', contextLong: 'An elite, independent unit is widely seen as necessary after State Capture. Critics say it can be politically weaponised. This tests your preference for strong, independent institutions vs. centralised control.', axes: { constitutionalLiberalism: 0.6, stateAuthority: -0.4, stability: 0.5, libertarian: 0.3 } },
  { id: 'q033', text: 'Corruption convicts should face mandatory life imprisonment.', theme: 'Security & Justice', weight: 1.0, contextShort: 'Corruption sentences vary widely and are often criticised as lenient.', contextLong: 'Mandatory life sentences would signal zero tolerance but remove judicial discretion and could be unconstitutional. This is about punishment vs. proportionality.', axes: { authoritarian: 0.6, constitutionalLiberalism: -0.4, stateAuthority: 0.4, libertarian: -0.5 } },
  { id: 'q034', text: 'Private security companies should have expanded arrest and investigation powers.', theme: 'Security & Justice', weight: 0.8, contextShort: 'Private security outnumbers SAPS in many areas.', contextLong: 'Expanding their powers could supplement an under-resourced police force but creates accountability risks and entrenches inequality between those who can afford protection and those who cannot.', axes: { economicRight: 0.5, libertarian: 0.4, stateAuthority: -0.3, authoritarian: 0.3 } },
  { id: 'q035', text: 'The NPA should be fully independent of the Minister of Justice.', theme: 'Security & Justice', weight: 1.1, contextShort: 'The National Prosecuting Authority is accountable to the Minister, raising concerns about political interference.', contextLong: 'Full independence is recommended by the Zondo Commission. This probes your commitment to prosecutorial independence vs. executive oversight.', axes: { constitutionalLiberalism: 0.7, stateAuthority: -0.6, secularDemocracy: 0.4, libertarian: 0.3 } },
  { id: 'q113', text: 'The military should be allowed to assist police in crime-fighting operations.', theme: 'Security & Justice', weight: 1.1, contextShort: 'The SANDF has been deployed domestically to quell unrest, but not for routine crime-fighting.', contextLong: 'Using the military in policing could provide much-needed manpower against armed criminals, but risks blurring the line between police and military, and could militarise civilian spaces.', axes: { authoritarian: 0.7, libertarian: -0.6, stateAuthority: 0.5 } },
  { id: 'q114', text: 'All police officers should wear body cameras while on duty.', theme: 'Security & Justice', weight: 0.9, contextShort: 'Body-worn cameras have been piloted in some stations but not rolled out nationally.', contextLong: 'Body cameras would provide evidence for complaints and protect both officers and civilians. Critics argue they are costly, raise privacy issues, and can be selectively switched off.', axes: { libertarian: 0.5, constitutionalLiberalism: 0.4, stateAuthority: -0.2 } },
  { id: 'q115', text: 'The parole system should be abolished for violent offenders.', theme: 'Security & Justice', weight: 1.0, contextShort: 'Parole is granted after serving a portion of the sentence, subject to good behaviour and rehabilitation.', contextLong: 'Abolishing parole for violent offenders would ensure they serve their full sentence, satisfying demands for retribution. Critics say it removes the incentive for rehabilitation and increases prison overcrowding.', axes: { authoritarian: 0.6, libertarian: -0.5, constitutionalLiberalism: -0.3 } },
  { id: 'q196', text: 'Domestic violence should be prosecuted as a public offence without requiring the complainant to press charges.', theme: 'Security & Justice', weight: 1.2, contextShort: 'Currently, victims must often maintain a complaint for prosecution to proceed, enabling withdrawals under pressure.', contextLong: 'State prosecution would protect victims from intimidation and close a common loophole. Critics argue it removes victim agency in complex family situations.', axes: { stateAuthority: 0.6, individualRights: 0.4, authoritarian: 0.3, libertarian: -0.3 } },
  { id: 'q197', text: 'The state should establish community policing forums with real authority, not just advisory roles.', theme: 'Security & Justice', weight: 1.0, contextShort: 'Community Policing Forums exist nationally but have no binding power over SAPS.', contextLong: 'Empowered CPFs would democratise policing and improve local accountability. Critics worry about community capture by vigilante elements.', axes: { constitutionalLiberalism: 0.4, libertarian: 0.4, stateAuthority: -0.3, transformation: 0.3 } },
  { id: 'q198', text: 'Plea bargains in serious criminal cases should require judicial approval, not just prosecutorial discretion.', theme: 'Security & Justice', weight: 0.9, contextShort: 'Plea deals are currently negotiated between prosecution and defence with limited judicial scrutiny.', contextLong: 'Judicial oversight would check against sweetheart deals and ensure public interest. Critics argue it slows down the justice system and undermines prosecutorial expertise.', axes: { constitutionalLiberalism: 0.5, stateAuthority: -0.2, stability: 0.3 } },
  { id: 'q199', text: 'Cash bail should be abolished and replaced with risk-based detention decisions.', theme: 'Security & Justice', weight: 1.0, contextShort: 'Cash bail disproportionately keeps poor accused persons in remand detention while wealthy accused walk free.', contextLong: 'Risk-based detention would assess flight risk and danger, not wealth. Critics worry about judicial capacity to assess risk reliably.', axes: { economicLeft: 0.5, constitutionalLiberalism: 0.4, individualRights: 0.5, authoritarian: -0.3 } },
  { id: 'q200', text: 'The SAPS should be depoliticised by placing appointment of the Commissioner under an independent body.', theme: 'Security & Justice', weight: 1.2, contextShort: 'The National Police Commissioner is appointed by the President, creating political vulnerability.', contextLong: 'An independent appointment process would insulate policing from political interference. Critics argue the Commissioner must be ultimately accountable to elected government.', axes: { constitutionalLiberalism: 0.7, stateAuthority: -0.6, stability: 0.4, libertarian: 0.3 } },
  { id: 'q201', text: 'Neighbourhood watch organisations should be formally recognised and regulated by law.', theme: 'Security & Justice', weight: 0.7, contextShort: 'Neighbourhood watches are widespread but operate in a legal grey area.', contextLong: 'Formal recognition would give them legitimacy and subject them to oversight, reducing vigilantism. Critics fear it would further entrench inequality in security provision.', axes: { economicRight: 0.3, constitutionalLiberalism: 0.2, stateAuthority: -0.2, libertarian: 0.4 } },

  // ════════════════════════════════════════════
  // FOREIGN POLICY (q036–q041, q119–q121, q202–q207)
  // ════════════════════════════════════════════
  { id: 'q036', text: 'South Africa should withdraw from the International Criminal Court.', theme: 'Foreign Policy', weight: 1.0, contextShort: 'The ANC government previously attempted withdrawal, then reversed.', contextLong: 'The ICC has been criticised as disproportionately targeting African leaders. Withdrawal would assert African legal sovereignty but weaken global accountability. This tests Pan-African vs. internationalist alignment.', axes: { panAfrican: 0.7, westernAlignment: -0.6, stateAuthority: 0.3 } },
  { id: 'q037', text: 'South Africa should leave BRICS.', theme: 'Foreign Policy', weight: 0.8, contextShort: 'SA joined BRICS in 2010, seeking alternatives to Western-dominated institutions.', contextLong: 'BRICS membership offers trade alternatives but aligns SA with authoritarian regimes. Leaving would signal a reorientation toward Western alliances.', axes: { westernAlignment: 0.5, panAfrican: -0.4, economicRight: 0.2 } },
  { id: 'q038', text: 'South Africa should maintain neutrality on the Russia-Ukraine war.', theme: 'Foreign Policy', weight: 0.9, contextShort: 'SA abstained from UN votes condemning Russia and hosted Russian naval exercises.', contextLong: 'A non-aligned stance is justified as principled multilateralism. Critics say it undermines human rights. This tests your preference for strategic independence vs. moral foreign policy.', axes: { panAfrican: 0.4, westernAlignment: -0.5, stateAuthority: 0.2 } },
  { id: 'q039', text: 'Immigration from other African countries should be unrestricted.', theme: 'Foreign Policy', weight: 0.9, contextShort: 'Xenophobic violence has flared periodically, especially in townships.', contextLong: 'Pan-Africanists argue for open borders in line with AU aspirations. Critics cite strain on services and jobs. This is the classic open-border vs. restrictionist debate.', axes: { panAfrican: 0.8, westernAlignment: -0.3, authoritarian: 0.2, libertarian: 0.4 } },
  { id: 'q040', text: 'South Africa should prioritise trade with China over the US and EU.', theme: 'Foreign Policy', weight: 1.0, contextShort: 'China is South Africa\'s largest trading partner.', contextLong: 'Deepening ties with China offers infrastructure investment but potentially at the cost of Western alliances and debt dependency. This tests your strategic alignment on the global stage.', axes: { panAfrican: -0.3, westernAlignment: -0.7, stateAuthority: 0.4, economicLeft: 0.5 } },
  { id: 'q041', text: 'The SANDF should only be deployed domestically for disaster relief, not protest control.', theme: 'Foreign Policy', weight: 0.7, contextShort: 'SANDF has been deployed during unrest, including July 2021 and service delivery protests.', contextLong: 'Using the military for domestic protest control can militarise civilian spaces. This question tests your stance on the military\'s role in a democracy.', axes: { libertarian: 0.6, constitutionalLiberalism: 0.5, stateAuthority: -0.4, authoritarian: -0.3 } },
  { id: 'q119', text: 'South Africa should offer asylum to political dissidents from any African country.', theme: 'Foreign Policy', weight: 0.9, contextShort: 'SA grants asylum on a case-by-case basis under the Refugees Act.', contextLong: 'A blanket policy of offering asylum would position SA as a continental sanctuary for democracy activists. Critics say it could strain resources and create diplomatic tensions with neighbouring states.', axes: { panAfrican: 0.7, westernAlignment: -0.3, libertarian: 0.5 } },
  { id: 'q120', text: 'South Africa should use its foreign policy to actively promote LGBTQ+ rights across Africa.', theme: 'Foreign Policy', weight: 0.8, contextShort: 'SA has one of the most progressive constitutions on sexual orientation, but many African countries criminalise homosexuality.', contextLong: 'Actively promoting LGBTQ+ rights would align foreign policy with constitutional values. Critics say it could be seen as neo-colonial imposition and alienate key allies.', axes: { libertarian: 0.6, westernAlignment: 0.5, panAfrican: -0.2 } },
  { id: 'q121', text: 'South Africa should provide military support to SADC peacekeeping missions.', theme: 'Foreign Policy', weight: 0.7, contextShort: 'The SANDF contributes to UN and AU peacekeeping, but SADC missions often face resource constraints.', contextLong: 'Increasing contributions would strengthen regional stability and SA\'s leadership role. Critics argue it strains the overstretched military and could entangle SA in foreign conflicts.', axes: { panAfrican: 0.6, stateAuthority: 0.4, libertarian: -0.2 } },
  { id: 'q202', text: 'South Africa should lead the establishment of an African Monetary Fund independent of the IMF.', theme: 'Foreign Policy', weight: 1.0, contextShort: 'The IMF\'s conditionalities have been criticised as undermining African economic sovereignty.', contextLong: 'An African Monetary Fund would provide balance-of-payments support without Western conditionalities. Critics say Africa lacks the reserve base for such a fund.', axes: { panAfrican: 0.8, westernAlignment: -0.6, economicLeft: 0.4 } },
  { id: 'q203', text: 'South Africa should recognise Palestinian statehood formally.', theme: 'Foreign Policy', weight: 0.9, contextShort: 'SA has strong historical solidarity with Palestine and has taken the issue of genocide in Gaza to the ICJ.', contextLong: 'Formal recognition aligns with SA\'s human rights foreign policy and solidarity tradition. Critics argue it limits SA\'s ability to play a neutral mediating role.', axes: { panAfrican: 0.5, westernAlignment: -0.5, constitutionalLiberalism: 0.4 } },
  { id: 'q204', text: 'South Africa should make Afrikaans a language of diplomacy alongside English.', theme: 'Foreign Policy', weight: 0.5, contextShort: 'English is effectively SA\'s diplomatic language despite the Constitution recognising eleven official languages.', contextLong: 'Including Afrikaans would recognise its unique origin and usage but is politically fraught. Critics argue that investing in African languages would be more consistent with Pan-African values.', axes: { traditionalAuthority: 0.3, westernAlignment: 0.2, transformation: -0.3 } },
  { id: 'q205', text: 'South Africa should increase foreign aid to SADC member states facing humanitarian crises.', theme: 'Foreign Policy', weight: 0.8, contextShort: 'SA contributes to regional stability but foreign aid spending is minimal given domestic needs.', contextLong: 'Increased aid would build goodwill and address regional instability. Critics argue SA cannot afford foreign generosity given domestic poverty.', axes: { panAfrican: 0.7, economicLeft: 0.3, westernAlignment: -0.2, stateAuthority: 0.2 } },
  { id: 'q206', text: 'South Africa should renegotiate all bilateral investment treaties that limit its policy space.', theme: 'Foreign Policy', weight: 0.9, contextShort: 'SA has cancelled several BITs since 2012 over concerns they constrained economic transformation.', contextLong: 'Renegotiation would restore flexibility for industrial policy and resource nationalisation. Critics warn it increases sovereign risk and deters FDI.', axes: { panAfrican: 0.4, economicLeft: 0.6, westernAlignment: -0.5, transformation: 0.4 } },
  { id: 'q207', text: 'South Africa should introduce visa-free travel for all African Union member states.', theme: 'Foreign Policy', weight: 0.9, contextShort: 'Free movement within the AU is an Agenda 2063 goal but SA maintains strict immigration controls.', contextLong: 'Visa-free travel would deepen continental integration and ease business. Critics cite pressure on services, crime, and irregular migration.', axes: { panAfrican: 0.8, westernAlignment: -0.3, authoritarian: 0.2, libertarian: 0.5 } },

  // ════════════════════════════════════════════
  // EDUCATION & HEALTH (q042–q045, q116–q118, q208–q213)
  // ════════════════════════════════════════════
  { id: 'q042', text: 'The National Health Insurance (NHI) should be the sole purchaser of healthcare.', theme: 'Education & Health', weight: 1.3, contextShort: 'NHI aims for universal health coverage but faces constitutional and fiscal challenges.', contextLong: 'The NHI Bill centralises health funding to eliminate inequality. Critics argue it eliminates private healthcare choice and risks fiscal collapse. This pits equality against individual choice.', axes: { economicLeft: 0.8, stateAuthority: 0.7, individualRights: -0.5, transformation: 0.4 } },
  { id: 'q043', text: 'Vaccination should be mandatory for all school-going children.', theme: 'Education & Health', weight: 1.0, contextShort: 'Childhood vaccination is currently recommended but not compulsory.', contextLong: 'Mandatory vaccination would improve public health outcomes but raises bodily autonomy and parental rights concerns. This tests the balance between public health and individual liberty.', axes: { authoritarian: 0.4, stateAuthority: 0.5, individualRights: -0.5, libertarian: -0.4 } },
  { id: 'q044', text: 'Traditional medicine should be fully integrated into the public healthcare system.', theme: 'Education & Health', weight: 0.9, contextShort: 'An estimated 80% of South Africans consult traditional healers.', contextLong: 'Integration would acknowledge cultural practice and expand access but raises regulatory, efficacy, and safety questions. This tests cultural inclusivity vs. scientific rigour.', axes: { traditionalAuthority: 0.6, secularDemocracy: -0.4, ubuntuCollectivism: 0.5, westernAlignment: -0.3 } },
  { id: 'q045', text: 'Free tertiary education should be extended to all students, regardless of household income.', theme: 'Education & Health', weight: 1.1, contextShort: 'Currently, free tertiary education is means-tested through NSFAS.', contextLong: 'Universal free education would remove barriers but is extremely costly. Means-tested funding targets the poorest but creates a "missing middle". This probes the universal vs. targeted welfare debate.', axes: { economicLeft: 0.7, transformation: 0.5, ubuntuCollectivism: 0.6, economicRight: -0.5 } },
  { id: 'q116', text: 'Public schools should be allowed to teach in only one language if the community demands it.', theme: 'Education & Health', weight: 0.9, contextShort: 'The Constitution protects the right to receive education in the language of choice where reasonably practicable.', contextLong: 'Single-medium schools are often seen as protecting minority languages and quality education, but they can also perpetuate segregation.', axes: { individualRights: 0.4, traditionalAuthority: 0.3, secularDemocracy: -0.2 } },
  { id: 'q117', text: 'The state should fund only one public broadcaster for educational content.', theme: 'Education & Health', weight: 0.6, contextShort: 'Multiple public broadcasters compete for limited funds, duplicating content.', contextLong: 'Consolidating educational broadcasting could save money and improve quality. Critics argue it would reduce diversity of voices and create a single point of editorial control.', axes: { stateAuthority: 0.4, libertarian: -0.3, economicLeft: 0.2 } },
  { id: 'q118', text: 'All healthcare workers should be required to report undocumented migrants to authorities.', theme: 'Education & Health', weight: 0.7, contextShort: 'Healthcare workers currently have no such obligation and are bound by patient confidentiality.', contextLong: 'Such a requirement would aid immigration enforcement but could deter migrants from seeking medical help, worsening public health.', axes: { authoritarian: 0.6, libertarian: -0.5, stateAuthority: 0.4 } },
  { id: 'q208', text: 'School governing bodies should have the power to set school fees without government approval.', theme: 'Education & Health', weight: 0.9, contextShort: 'Section 39 schools set fees subject to exemption for poor parents, but government caps apply.', contextLong: 'Greater autonomy would allow well-resourced schools to maintain quality. Critics say it entrenches inequality between rich and poor schools.', axes: { economicRight: 0.5, individualRights: 0.4, transformation: -0.4, constitutionalLiberalism: -0.2 } },
  { id: 'q209', text: 'Mental health services should receive the same budget allocation as physical health.', theme: 'Education & Health', weight: 1.1, contextShort: 'Mental health receives less than 5% of South Africa\'s health budget despite a high burden of disease.', contextLong: 'Parity of budget allocation would address the systematic underinvestment in mental health. Critics argue physical health emergencies must be prioritised given resource constraints.', axes: { economicLeft: 0.6, transformation: 0.4, stateAuthority: 0.3, westernAlignment: 0.2 } },
  { id: 'q210', text: 'Early childhood development (ECD) should be made compulsory from age 3.', theme: 'Education & Health', weight: 1.0, contextShort: 'Attendance at Grade R is not compulsory, and many children start formal school at age 7.', contextLong: 'Compulsory ECD from age 3 would dramatically improve school readiness and lifetime outcomes. Critics question capacity, cost, and parental choice.', axes: { stateAuthority: 0.5, economicLeft: 0.5, transformation: 0.4, libertarian: -0.3 } },
  { id: 'q211', text: 'Corporal punishment should be banned in all private and faith schools.', theme: 'Education & Health', weight: 1.1, contextShort: 'Corporal punishment was banned in public schools in 1996 but is still practised in some private and faith schools.', contextLong: 'A complete ban would align with the Children\'s Act and international standards. Religious schools argue it is a parental rights and faith-based discipline matter.', axes: { secularDemocracy: 0.6, stateAuthority: 0.4, libertarian: -0.4, traditionalAuthority: -0.5 } },
  { id: 'q212', text: 'South Africa should fund research into African traditional medicines through the MRC.', theme: 'Education & Health', weight: 0.8, contextShort: 'The Medical Research Council funds biomedical research but traditional medicine research is marginal.', contextLong: 'Funding traditional medicine research would generate evidence and build cultural legitimacy. Critics worry about diverting limited research funds from proven biomedical science.', axes: { ubuntuCollectivism: 0.5, traditionalAuthority: 0.5, secularDemocracy: -0.3, westernAlignment: -0.2 } },
  { id: 'q213', text: 'Universities should be required to teach at least one African language as a medium of instruction.', theme: 'Education & Health', weight: 1.0, contextShort: 'South African universities teach almost exclusively in English, marginalising students from African-language backgrounds.', contextLong: 'Introducing African languages as instruction media would decolonise higher education and improve comprehension. Critics cite the cost of developing academic corpora and potential quality concerns.', axes: { transformation: 0.7, racialRedress: 0.5, ubuntuCollectivism: 0.5, westernAlignment: -0.4 } },

  // ════════════════════════════════════════════
  // ENVIRONMENT (q046–q049, q097, q122–q124, q214–q218)
  // ════════════════════════════════════════════
  { id: 'q046', text: 'The coal industry should be phased out within 10 years.', theme: 'Environment', weight: 1.0, contextShort: 'SA is the 14th largest emitter of CO₂, heavily reliant on coal for electricity.', contextLong: 'A rapid phase-out threatens jobs and energy security but is urged by climate scientists. The Just Energy Transition framework seeks a balanced approach. This tests ecological urgency vs. economic pragmatism.', axes: { economicLeft: 0.3, transformation: 0.4, westernAlignment: 0.2, stability: -0.3 } },
  { id: 'q047', text: 'Fracking should be permitted in the Karoo to boost energy supply.', theme: 'Environment', weight: 1.1, contextShort: 'The Karoo basin potentially holds significant shale gas reserves.', contextLong: 'Fracking could provide energy security and jobs but risks water contamination in a water-scarce region. This is a direct resource development vs. environmental protection trade-off.', axes: { economicRight: 0.5, stability: 0.4, transformation: -0.3, westernAlignment: 0.3 } },
  { id: 'q048', text: 'South Africa should implement a carbon tax on all industries.', theme: 'Environment', weight: 0.9, contextShort: 'A phased carbon tax already exists but with significant exemptions.', contextLong: 'A comprehensive carbon tax would accelerate decarbonisation but could increase costs for consumers. This tests your willingness to use tax policy for environmental goals.', axes: { economicLeft: 0.4, westernAlignment: 0.5, transformation: 0.3, economicRight: -0.4 } },
  { id: 'q049', text: 'Rhino horn trade should be legalised to fund conservation.', theme: 'Environment', weight: 0.7, contextShort: 'Rhino horn trade is banned internationally under CITES.', contextLong: 'Legalisation could fund conservation through regulated sales but may increase demand and poaching. This tests market-based conservation vs. strict protection.', axes: { economicRight: 0.4, libertarian: 0.3, westernAlignment: -0.3, stateAuthority: -0.2 } },
  { id: 'q097', text: 'The state should subsidise electric vehicle purchases to accelerate adoption.', theme: 'Environment', weight: 0.7, contextShort: 'Electric vehicle uptake is low in SA, constrained by cost and infrastructure.', contextLong: 'Subsidies could jump-start the green transition but are costly and may benefit wealthier buyers. This tests your willingness to use public funds for environmental goals.', axes: { economicLeft: 0.4, transformation: 0.3, westernAlignment: 0.2 } },
  { id: 'q122', text: 'Plastic bags should be banned entirely.', theme: 'Environment', weight: 0.7, contextShort: 'South Africa has a plastic bag levy but no outright ban.', contextLong: 'A ban would drastically reduce plastic waste and litter, but would impact the plastics industry and consumer convenience.', axes: { stateAuthority: 0.5, economicLeft: 0.3, westernAlignment: 0.3 } },
  { id: 'q123', text: 'New coal mines should be prohibited, even if they create jobs.', theme: 'Environment', weight: 1.1, contextShort: 'Coal remains a major employer in Mpumalanga, but is the biggest contributor to SA\'s carbon emissions.', contextLong: 'Prohibiting new coal mines would accelerate the energy transition but could devastate coal-dependent communities. This probes the just transition dilemma: environment versus jobs.', axes: { transformation: 0.4, economicLeft: 0.3, stability: -0.4 } },
  { id: 'q124', text: 'Game farms should be taxed at a higher rate than agricultural farms.', theme: 'Environment', weight: 0.6, contextShort: 'Game farming for hunting and eco-tourism is a growing sector, but critics say it entrenches land inequality.', contextLong: 'A higher tax could encourage productive agricultural use of land and generate revenue. Opponents argue game farms provide conservation benefits and jobs.', axes: { economicLeft: 0.4, transformation: 0.3, racialRedress: 0.2 } },
  { id: 'q214', text: 'Eskom should be broken up into separate generation, transmission, and distribution entities.', theme: 'Environment', weight: 1.2, contextShort: 'Eskom is a vertically integrated monopoly widely blamed for South Africa\'s electricity crisis.', contextLong: 'Unbundling would allow competition in generation and improve efficiency. Critics argue coordination problems could worsen reliability in the short term.', axes: { economicRight: 0.6, stateAuthority: -0.4, stability: 0.3, transformation: -0.2 } },
  { id: 'q215', text: 'Water should be recognised as a constitutional right with a free basic allocation for all.', theme: 'Environment', weight: 1.1, contextShort: 'The right to water is implied in the Constitution but not explicitly guaranteed.', contextLong: 'An explicit right with a free basic allocation would protect poor households from disconnection. Critics say free water creates a culture of non-payment and is fiscally unsustainable.', axes: { economicLeft: 0.7, transformation: 0.5, constitutionalLiberalism: 0.3, economicRight: -0.4 } },
  { id: 'q216', text: 'Hunting of the Big Five for sport should be banned.', theme: 'Environment', weight: 0.9, contextShort: 'Trophy hunting generates significant revenue but faces growing ethical opposition.', contextLong: 'A ban would satisfy moral objections to killing endangered species for sport but could reduce conservation funding. This tests ethical conservation versus market-based wildlife management.', axes: { westernAlignment: 0.4, economicLeft: 0.3, libertarian: -0.4, stateAuthority: 0.3 } },
  { id: 'q217', text: 'South Africa should declare a national climate emergency with emergency powers.', theme: 'Environment', weight: 1.0, contextShort: 'Several countries have declared climate emergencies, unlocking special executive powers.', contextLong: 'Emergency powers would allow rapid action on decarbonisation and adaptation. Critics fear they concentrate executive power and bypass democratic processes.', axes: { stateAuthority: 0.5, economicLeft: 0.4, authoritarian: 0.3, constitutionalLiberalism: -0.3 } },
  { id: 'q218', text: 'Developers should be required to offset all carbon emissions before receiving planning permission.', theme: 'Environment', weight: 0.8, contextShort: 'Environmental impact assessments exist but mandatory carbon offsetting is not required.', contextLong: 'Mandatory offsets would internalise environmental costs. Critics say they add to housing costs and may only create paper carbon markets.', axes: { economicLeft: 0.4, westernAlignment: 0.4, economicRight: -0.3, stateAuthority: 0.3 } },

  // ════════════════════════════════════════════
  // SA HISTORICAL EVENTS (q050–q053, q125–q128, q219–q222)
  // ════════════════════════════════════════════
  { id: 'q050', text: 'The Marikana massacre should be commemorated as a national day of remembrance.', theme: 'SA Historical Events', weight: 1.0, contextShort: '34 striking miners were killed by police at Marikana in 2012.', contextLong: 'Official commemoration would acknowledge state violence against workers. Some argue it could deepen social division. This probes your willingness to confront uncomfortable history vs. move on.', axes: { transformation: 0.6, economicLeft: 0.5, racialRedress: 0.4, stateAuthority: -0.3 } },
  { id: 'q051', text: 'The Truth and Reconciliation Commission succeeded in healing South Africa.', theme: 'SA Historical Events', weight: 1.2, contextShort: 'The TRC granted amnesty for full disclosure of political crimes during apartheid.', contextLong: 'The TRC is praised internationally but criticised for prioritising truth over justice and failing to address economic crimes. This probes your view of restorative vs. retributive justice.', axes: { transformation: 0.4, stability: 0.5, ubuntuCollectivism: 0.6, racialRedress: 0.3 } },
  { id: 'q052', text: 'Those responsible for State Capture should be permanently barred from public office.', theme: 'SA Historical Events', weight: 1.1, contextShort: 'The Zondo Commission made extensive findings but prosecutions remain slow.', contextLong: 'Permanent disqualification would protect the state from corrupt actors but could be seen as harsh and denying redemption. This is about accountability vs. forgiveness.', axes: { constitutionalLiberalism: 0.5, authoritarian: 0.4, transformation: 0.3, stability: 0.4 } },
  { id: 'q053', text: 'The July 2021 unrest was primarily a political insurrection, not spontaneous protest.', theme: 'SA Historical Events', weight: 1.0, contextShort: 'The July 2021 unrest killed 354 people and caused R50 billion in damage.', contextLong: 'Characterising it as an insurrection implies orchestrated political motive. Others argue it was a mix of protest, criminality, and poverty-driven desperation. This probes your interpretation of a pivotal event.', axes: { stateAuthority: 0.4, stability: -0.5, transformation: -0.3, authoritarian: 0.3 } },
  { id: 'q125', text: 'The government should formally apologise for the Marikana massacre.', theme: 'SA Historical Events', weight: 1.0, contextShort: 'The Farlam Commission found that police actions were unjustified, but no formal state apology has been issued.', contextLong: 'A formal apology would acknowledge state violence and offer a measure of closure to victims\' families. Critics say apologies are cheap without material compensation.', axes: { transformation: 0.5, stateAuthority: -0.4, racialRedress: 0.3 } },
  { id: 'q126', text: 'Apartheid should be declared a crime against humanity in South African law.', theme: 'SA Historical Events', weight: 1.2, contextShort: 'International law recognises apartheid as a crime against humanity, but domestic law does not explicitly codify it as such.', contextLong: 'Codifying it would be a powerful symbolic act and could open legal avenues for victims. Critics say it is retrospective legislation that could undermine the TRC\'s amnesty agreements.', axes: { transformation: 0.7, racialRedress: 0.8, constitutionalLiberalism: -0.4 } },
  { id: 'q127', text: 'The government should pay reparations to victims of the July 2021 unrest.', theme: 'SA Historical Events', weight: 0.8, contextShort: 'The unrest caused widespread destruction, but many victims were uninsured and received no state compensation.', contextLong: 'Reparations would help rebuild lives and restore trust in the state. Opponents say it would reward lawlessness and create a moral hazard.', axes: { stateAuthority: 0.5, transformation: 0.4, stability: -0.3 } },
  { id: 'q128', text: 'The 1956 Women\'s March should be a national holiday.', theme: 'SA Historical Events', weight: 0.7, contextShort: 'The march protested pass laws and was a pivotal moment in the liberation struggle, but is not a public holiday.', contextLong: 'Making it a holiday would honour women\'s contribution to democracy. Critics say South Africa already has too many public holidays.', axes: { transformation: 0.4, secularDemocracy: 0.2, racialRedress: 0.3 } },
  { id: 'q219', text: 'The apartheid regime\'s beneficiaries should pay reparations to those who suffered.', theme: 'SA Historical Events', weight: 1.4, contextShort: 'The TRC recommended reparations but they were never fully implemented.', contextLong: 'Comprehensive reparations would provide material redress for a century of dispossession and abuse. Critics question who pays, who receives, and whether it would be constitutional.', axes: { racialRedress: 0.9, transformation: 0.8, nonRacialism: -0.5, economicRight: -0.6 } },
  { id: 'q220', text: 'The name "South Africa" should be changed to an African name to decolonise national identity.', theme: 'SA Historical Events', weight: 0.7, contextShort: 'Several African countries renamed themselves after independence; SA retained its colonial-era name.', contextLong: 'Renaming would be a powerful symbolic decolonisation. Critics say the cost and administrative disruption are not justified.', axes: { transformation: 0.5, racialRedress: 0.4, panAfrican: 0.5, stability: -0.3 } },
  { id: 'q221', text: 'Statues of colonial figures on public land should be removed.', theme: 'SA Historical Events', weight: 1.0, contextShort: 'The Rhodes Must Fall movement accelerated debate, but many colonial statues remain.', contextLong: 'Removal would cleanse public space of symbols of oppression. Critics argue statues should be contextualised, not erased.', axes: { transformation: 0.7, racialRedress: 0.6, nonRacialism: -0.3, westernAlignment: -0.2 } },
  { id: 'q222', text: 'The 1994 Constitution should be entirely rewritten for a second democratic transition.', theme: 'SA Historical Events', weight: 1.3, contextShort: 'Some argue the negotiated settlement entrenched economic inequality and requires a clean break.', contextLong: 'A new constitution could better address economic rights and transformation. Critics argue it would create enormous instability and legal uncertainty.', axes: { transformation: 0.8, economicLeft: 0.6, constitutionalLiberalism: -0.7, stability: -0.8 } },

  // ════════════════════════════════════════════
  // PHILOSOPHY & THEORY (q054–q057, q129–q131, q223–q226)
  // ════════════════════════════════════════════
  { id: 'q054', text: 'Individual rights should take precedence over collective cultural rights.', theme: 'Philosophy & Theory', weight: 1.1, contextShort: 'The Bill of Rights protects both individual and collective cultural rights.', contextLong: 'Prioritising individual rights aligns with liberal democracy; prioritising collective cultural rights aligns with African communitarianism (ubuntu). The Constitution balances both. This probes your foundational philosophical alignment.', axes: { individualRights: 0.7, ubuntuCollectivism: -0.6, libertarian: 0.5, traditionalAuthority: -0.4 } },
  { id: 'q055', text: 'Class inequality is a more fundamental problem in South Africa than racial inequality.', theme: 'Philosophy & Theory', weight: 1.3, contextShort: 'South Africa has intersecting race and class inequalities rooted in apartheid and colonialism.', contextLong: 'A class-first analysis argues that economic inequality affects all poor people regardless of race. A race-first analysis argues that racial inequality persists independently of class. This is a defining ideological divide.', axes: { nonRacialism: 0.5, economicLeft: 0.6, racialRedress: -0.4, transformation: 0.3 } },
  { id: 'q056', text: 'The right to resist unjust laws is a fundamental democratic principle.', theme: 'Philosophy & Theory', weight: 1.0, contextShort: 'Civil disobedience has a long history in South Africa, from the Defiance Campaign to Fees Must Fall.', contextLong: 'Recognising a right to resist honours liberation history but could undermine the rule of law. This tests revolutionary spirit vs. constitutional order.', axes: { libertarian: 0.6, transformation: 0.5, stateAuthority: -0.5, stability: -0.4 } },
  { id: 'q057', text: 'South Africa\'s Constitution is a transformative document, not merely a framework for governance.', theme: 'Philosophy & Theory', weight: 0.9, contextShort: 'The Constitution explicitly commits to redressing historical injustice and transforming society.', contextLong: 'A transformative view demands active state intervention to change society. A procedural view sees the Constitution as rules for governance. This probes your interpretation of the constitutional project.', axes: { transformation: 0.6, constitutionalLiberalism: 0.3, economicLeft: 0.4, stability: -0.2 } },
  { id: 'q129', text: 'The concept of ubuntu should be justiciable in South African courts.', theme: 'Philosophy & Theory', weight: 1.0, contextShort: 'Ubuntu is mentioned in the Constitution\'s founding provisions but is not directly enforceable.', contextLong: 'Making ubuntu justiciable would give it legal force, potentially influencing decisions on community rights and restorative justice. Critics say it is too vague and could lead to judicial activism.', axes: { ubuntuCollectivism: 0.8, individualRights: -0.3, traditionalAuthority: 0.5 } },
  { id: 'q130', text: 'South Africa should adopt a maximalist interpretation of its Constitution to achieve transformation.', theme: 'Philosophy & Theory', weight: 0.9, contextShort: 'Judges debate whether the Constitution should be read narrowly (textually) or broadly (purposively).', contextLong: 'A maximalist approach would allow courts to mandate positive state action to redress inequality. Critics say it undermines separation of powers and makes judges policy-makers.', axes: { transformation: 0.7, constitutionalLiberalism: -0.3, stateAuthority: 0.5 } },
  { id: 'q131', text: 'Freedom of expression should not protect speech that offends religious sensibilities.', theme: 'Philosophy & Theory', weight: 0.8, contextShort: 'The Constitution protects free expression but allows limitation for hate speech and incitement.', contextLong: 'Adding religious sensitivity as a ground for limitation would protect communities but could severely restrict artistic and political expression.', axes: { authoritarian: 0.4, traditionalAuthority: 0.5, libertarian: -0.5 } },
  { id: 'q223', text: 'Economic rights (housing, food, healthcare) should be as legally enforceable as civil and political rights.', theme: 'Philosophy & Theory', weight: 1.2, contextShort: 'Civil rights are directly enforceable; socio-economic rights are progressively realisable.', contextLong: 'Full enforceability would allow courts to order the state to deliver housing or food. Critics say the separation of powers prevents courts from setting budgets.', axes: { economicLeft: 0.7, constitutionalLiberalism: 0.3, transformation: 0.6, stateAuthority: 0.4 } },
  { id: 'q224', text: 'Decolonisation of knowledge is as important as economic decolonisation.', theme: 'Philosophy & Theory', weight: 1.0, contextShort: 'Calls to decolonise universities challenged Western epistemology as the sole framework for knowledge.', contextLong: 'Epistemic decolonisation would centre African philosophies and knowledge systems in education. Critics argue it risks relativism and weakening scientific rigour.', axes: { transformation: 0.7, racialRedress: 0.6, ubuntuCollectivism: 0.6, westernAlignment: -0.5 } },
  { id: 'q225', text: 'A just society requires equality of outcome, not merely equality of opportunity.', theme: 'Philosophy & Theory', weight: 1.3, contextShort: 'Liberal theory emphasises equal opportunity; socialist theory demands equal outcomes.', contextLong: 'Outcome equality would require active redistribution until material conditions converge. Critics argue it violates individual freedom and requires coercive state intervention.', axes: { economicLeft: 0.8, transformation: 0.7, individualRights: -0.5, economicRight: -0.7 } },
  { id: 'q226', text: 'Pan-Africanism should be the guiding ideology of South African foreign and domestic policy.', theme: 'Philosophy & Theory', weight: 1.0, contextShort: 'Pan-Africanism emphasises African unity, sovereignty, and solidarity.', contextLong: 'A Pan-Africanist framework would prioritise African interests across policy areas. Critics argue it is too vague to guide concrete policy and can be used to shield authoritarian regimes.', axes: { panAfrican: 0.9, westernAlignment: -0.7, transformation: 0.5, constitutionalLiberalism: -0.2 } },

  // ════════════════════════════════════════════
  // RACE & IDENTITY (q058–q061, q132–q134, q227–q231)
  // ════════════════════════════════════════════
  { id: 'q058', text: 'White South Africans have a collective responsibility to address apartheid\'s legacy.', theme: 'Race & Identity', weight: 1.4, contextShort: 'The TRC framed reconciliation as a shared project, but material inequality persists along racial lines.', contextLong: 'Collective responsibility argues that beneficiaries of historical injustice have a duty to redress it. Critics argue for individual, not group, responsibility. This directly tests your stance on race and redress.', axes: { racialRedress: 0.8, transformation: 0.7, nonRacialism: -0.6, ubuntuCollectivism: 0.5 } },
  { id: 'q059', text: 'Coloured identity should be recognised as a distinct indigenous identity, not a mixed-race residual category.', theme: 'Race & Identity', weight: 1.2, contextShort: 'The coloured community has historically been classified as a residual category under apartheid.', contextLong: 'Recognition as a distinct identity would affirm cultural heritage and strengthen claims for land and resources. Critics argue it entrenches apartheid categories. This probes your approach to identity politics.', axes: { racialRedress: 0.5, nonRacialism: -0.4, traditionalAuthority: 0.3, transformation: 0.3 } },
  { id: 'q060', text: 'Khoisan people should receive First Nation status with associated land and cultural rights.', theme: 'Race & Identity', weight: 1.1, contextShort: 'The Khoisan were displaced before and during colonisation, predating apartheid.', contextLong: 'First Nation status would recognise them as the original inhabitants with distinct rights. The legal and land implications are complex. This tests your support for indigenous rights.', axes: { racialRedress: 0.7, traditionalAuthority: 0.6, transformation: 0.5, nonRacialism: -0.5 } },
  { id: 'q061', text: 'South Africa should abolish racial classification in official documents.', theme: 'Race & Identity', weight: 1.0, contextShort: 'Post-1994, racial classification continues for transformation and statistical purposes.', contextLong: 'Abolition would realise a non-racial ideal but could make it impossible to measure and address ongoing racial inequality. This is the ultimate test of non-racialism vs. race-conscious policy.', axes: { nonRacialism: 0.9, racialRedress: -0.8, individualRights: 0.4, transformation: -0.3 } },
  { id: 'q132', text: 'South Africa should establish a museum of apartheid in every province.', theme: 'Race & Identity', weight: 0.7, contextShort: 'The Apartheid Museum in Johannesburg is the only major museum dedicated solely to apartheid.', contextLong: 'Provincial museums would make history accessible and educate younger generations. Critics say the money could be better spent on direct redress.', axes: { transformation: 0.4, racialRedress: 0.5, economicLeft: 0.2 } },
  { id: 'q133', text: 'Racially exclusive organisations should be prohibited from receiving any state funding.', theme: 'Race & Identity', weight: 1.1, contextShort: 'Some cultural and sports bodies remain predominantly one race and receive state support.', contextLong: 'Cutting funding would pressure organisations to transform. Opponents say it punishes community-based organisations for historical patterns beyond their control.', axes: { nonRacialism: 0.6, racialRedress: -0.5, stateAuthority: 0.4 } },
  { id: 'q134', text: 'The term "coloured" should be replaced with "Khoisan" in official use.', theme: 'Race & Identity', weight: 0.9, contextShort: 'Many coloured people identify as Khoisan descendants and reject the apartheid-era classification.', contextLong: 'Renaming would recognise indigenous heritage and self-identification. Critics argue it imposes a single identity on a diverse community and erases other lineages.', axes: { racialRedress: 0.4, nonRacialism: -0.3, traditionalAuthority: 0.5 } },
  { id: 'q227', text: 'Indian and Chinese South Africans should be included in all BEE beneficiary categories equally.', theme: 'Race & Identity', weight: 1.0, contextShort: 'The status of Indian and Chinese South Africans under BEE has been contested in courts.', contextLong: 'Full inclusion recognises the discrimination these communities faced under apartheid. Critics argue that as relatively advantaged minorities, their inclusion dilutes redress for black Africans.', axes: { racialRedress: 0.4, nonRacialism: -0.3, transformation: 0.3, constitutionalLiberalism: 0.3 } },
  { id: 'q228', text: 'Afrikaner cultural heritage should receive equal state protection to other cultural heritages.', theme: 'Race & Identity', weight: 0.9, contextShort: 'The state funds various cultural institutions but Afrikaner cultural institutions have faced particular scrutiny.', contextLong: 'Equal protection would apply non-racialism consistently to all groups. Critics argue Afrikaner culture was historically privileged by the apartheid state and cannot claim equal disadvantage.', axes: { nonRacialism: 0.5, westernAlignment: 0.3, transformation: -0.3, racialRedress: -0.4 } },
  { id: 'q229', text: 'South Africa should actively recruit its diaspora professionals back through incentive programmes.', theme: 'Race & Identity', weight: 0.9, contextShort: 'Brain drain has cost SA many of its most skilled professionals across all racial groups.', contextLong: 'Incentive programmes could reverse skills losses and bring back experienced professionals. Critics question affordability and whether incentives alone address root causes of emigration.', axes: { economicRight: 0.3, transformation: 0.3, westernAlignment: 0.2, stability: 0.3 } },
  { id: 'q230', text: 'The San people should be given veto rights over research conducted on their genetic heritage.', theme: 'Race & Identity', weight: 0.8, contextShort: 'San genetic material has been used in research without adequate prior informed consent.', contextLong: 'Veto rights would apply indigenous data sovereignty principles and correct historical exploitation. Critics argue it could impede medical research of benefit to all.', axes: { racialRedress: 0.6, traditionalAuthority: 0.5, ubuntuCollectivism: 0.5, westernAlignment: -0.3 } },
  { id: 'q231', text: 'Affirmative action should sunset 30 years after the end of apartheid (i.e., by 2024).', theme: 'Race & Identity', weight: 1.3, contextShort: 'Some argue that affirmative action has served its purpose; others say inequality remains too deep.', contextLong: 'Sunsetting would force a transition to needs-based policy. Opponents argue that three decades have barely scratched the surface of economic transformation.', axes: { nonRacialism: 0.7, racialRedress: -0.8, economicRight: 0.5, transformation: -0.6 } },

  // ════════════════════════════════════════════
  // YOUTH & CULTURE (q062–q064, q135–q137, q232–q235)
  // ════════════════════════════════════════════
  { id: 'q062', text: 'South Africa should implement mandatory national service for youth.', theme: 'Youth & Culture', weight: 0.8, contextShort: 'National service was compulsory for white males under apartheid; now voluntary.', contextLong: 'A revived national service could include military, community, or environmental work. Proponents see it as nation-building; critics call it forced labour.', axes: { authoritarian: 0.5, stateAuthority: 0.4, libertarian: -0.6, ubuntuCollectivism: 0.3 } },
  { id: 'q063', text: 'Student debt should be cancelled for all graduates earning below R500,000/year.', theme: 'Youth & Culture', weight: 1.0, contextShort: 'Student debt in South Africa exceeds R16 billion, trapping graduates in financial precarity.', contextLong: 'Cancellation would free a generation for economic participation but is costly and could be seen as unfair to those who paid or did not attend university.', axes: { economicLeft: 0.6, transformation: 0.5, ubuntuCollectivism: 0.4, economicRight: -0.4 } },
  { id: 'q064', text: 'The voting age should be lowered to 16.', theme: 'Youth & Culture', weight: 0.9, contextShort: 'The current voting age is 18, as per the Constitution.', contextLong: 'Lowering the voting age would give youth a stronger voice in policy. Critics question whether 16-year-olds have sufficient political maturity.', axes: { libertarian: 0.5, individualRights: 0.4, constitutionalLiberalism: 0.3, stability: -0.2 } },
  { id: 'q135', text: 'The national curriculum should include a mandatory course on South African political history.', theme: 'Youth & Culture', weight: 1.0, contextShort: 'History is optional after Grade 9, and many learners leave school without deep knowledge of the liberation struggle.', contextLong: 'Making it mandatory would ensure every citizen understands the country\'s past. Critics say it could become a vehicle for political indoctrination and overburden the curriculum.', axes: { transformation: 0.5, stateAuthority: 0.3, secularDemocracy: 0.2 } },
  { id: 'q136', text: 'The voting age should be lowered to 16 for municipal elections only.', theme: 'Youth & Culture', weight: 0.8, contextShort: 'Some countries allow voting at 16 for local elections, where issues directly affect young people.', contextLong: 'This would introduce youth gradually to voting, focusing on local issues they experience. Critics say it creates a two-tier citizenship and that 16-year-olds are not ready for any voting.', axes: { libertarian: 0.5, individualRights: 0.4, stability: -0.2 } },
  { id: 'q137', text: 'Public universities should be allowed to set their own admission criteria, including race.', theme: 'Youth & Culture', weight: 1.2, contextShort: 'Universities currently use race as one factor in admissions to promote transformation, but this is legally contested.', contextLong: 'Allowing autonomous criteria gives institutions flexibility to address historical disadvantage. Critics say it can lead to inconsistent standards and reverse discrimination.', axes: { constitutionalLiberalism: 0.3, racialRedress: 0.5, nonRacialism: -0.4 } },
  { id: 'q232', text: 'All South African schools should teach coding and computer science from Grade 4.', theme: 'Youth & Culture', weight: 0.9, contextShort: 'Coding is taught in some schools but is far from universal.', contextLong: 'Universal coding education would prepare youth for the digital economy. Critics question whether basic literacy and numeracy should not be prioritised first.', axes: { economicRight: 0.3, westernAlignment: 0.3, transformation: 0.3, stateAuthority: 0.2 } },
  { id: 'q233', text: 'Youth gangs should be rehabilitated through state-funded economic inclusion programmes, not imprisonment.', theme: 'Youth & Culture', weight: 1.0, contextShort: 'Gang violence is endemic in Cape Flats and other townships, with prosecution-only approaches showing little effect.', contextLong: 'Economic inclusion addresses root causes of gang membership. Critics argue it rewards criminal behaviour.', axes: { economicLeft: 0.6, libertarian: 0.3, authoritarian: -0.5, ubuntuCollectivism: 0.5 } },
  { id: 'q234', text: 'The National Youth Development Agency should be replaced by a public-private youth employment fund.', theme: 'Youth & Culture', weight: 0.8, contextShort: 'The NYDA has been criticised for wasteful expenditure and poor outcomes.', contextLong: 'A public-private fund could combine state reach with private sector efficiency. Critics argue it would reduce accountability and potentially exclude the most marginalised youth.', axes: { economicRight: 0.4, stateAuthority: -0.3, transformation: 0.2, stability: 0.2 } },
  { id: 'q235', text: 'Social media influencers who promote products to South African audiences should pay local tax.', theme: 'Youth & Culture', weight: 0.7, contextShort: 'The tax obligations of social media influencers are poorly regulated in South Africa.', contextLong: 'Taxing influencer income would close a growing tax gap. Critics say regulation is complex and may push influencers to overseas platforms.', axes: { economicLeft: 0.4, stateAuthority: 0.4, economicRight: -0.2, westernAlignment: -0.2 } },

  // ════════════════════════════════════════════
  // GENDER & FAMILY (q065–q068, q138–q140, q165, q236–q240)
  // ════════════════════════════════════════════
  { id: 'q065', text: 'Political parties should be required to have 50% female candidates on their lists.', theme: 'Gender & Family', weight: 1.0, contextShort: 'South Africa has high female parliamentary representation but not always 50%.', contextLong: 'Mandatory quotas would accelerate gender equality but could be seen as tokenistic or undermining merit-based selection.', axes: { secularDemocracy: 0.5, individualRights: 0.6, traditionalAuthority: -0.4, libertarian: 0.3 } },
  { id: 'q066', text: 'Paid paternity leave should be equal to maternity leave (4 months).', theme: 'Gender & Family', weight: 0.9, contextShort: 'Currently, fathers are entitled to 10 days of parental leave.', contextLong: 'Equal leave would normalise caregiving roles and reduce workplace discrimination against women but is costly for businesses.', axes: { individualRights: 0.6, libertarian: 0.4, traditionalAuthority: -0.5, economicLeft: 0.3 } },
  { id: 'q067', text: 'Surrogacy should be freely available without restriction.', theme: 'Gender & Family', weight: 0.8, contextShort: 'Surrogacy is legal in South Africa but regulated.', contextLong: 'Expanding access to surrogacy would help infertile couples and same-sex families but raises ethical and commercial concerns.', axes: { libertarian: 0.5, individualRights: 0.5, traditionalAuthority: -0.4, secularDemocracy: 0.3 } },
  { id: 'q068', text: 'GBV should be treated as a national emergency with dedicated courts and funding.', theme: 'Gender & Family', weight: 1.3, contextShort: 'South Africa has one of the highest rates of gender-based violence globally.', contextLong: 'Declaring a national emergency would unlock resources and fast-track prosecutions. The scale of the crisis demands extraordinary measures.', axes: { stateAuthority: 0.5, authoritarian: 0.4, individualRights: 0.6, transformation: 0.3 } },
  { id: 'q138', text: 'Marital rape should be explicitly criminalised, removing the common-law defence.', theme: 'Gender & Family', weight: 1.1, contextShort: 'South Africa\'s courts have ruled that marital rape is a crime, but it is not explicitly stated in statute.', contextLong: 'Explicit criminalisation would remove any ambiguity and send a strong message against domestic violence. Some religious groups argue it interferes with marital relations.', axes: { individualRights: 0.7, traditionalAuthority: -0.6, libertarian: 0.4 } },
  { id: 'q139', text: 'The state should provide free sanitary products to all menstruating persons.', theme: 'Gender & Family', weight: 0.8, contextShort: 'Period poverty affects millions of learners who miss school during menstruation.', contextLong: 'Free provision would improve educational outcomes and gender equity. Critics say it is an unsustainable fiscal burden.', axes: { economicLeft: 0.6, transformation: 0.4, individualRights: 0.5 } },
  { id: 'q140', text: 'Lobola should be regulated to prevent financial exploitation.', theme: 'Gender & Family', weight: 0.7, contextShort: 'Lobola is a customary practice of bride wealth, unregulated by the state.', contextLong: 'Regulation could cap amounts and prevent abuse, but would be seen as state interference in cultural practices.', axes: { traditionalAuthority: -0.4, secularDemocracy: 0.5, economicLeft: 0.2 } },
  { id: 'q165', text: 'South Africa should have a quota for women in traditional leadership positions.', theme: 'Gender & Family', weight: 0.9, contextShort: 'Traditional councils are overwhelmingly male, despite constitutional commitments to gender equality.', contextLong: 'A quota would advance gender representation in a deeply patriarchal institution. Critics say it interferes with customary law.', axes: { individualRights: 0.7, traditionalAuthority: -0.5, secularDemocracy: 0.4 } },
  { id: 'q236', text: 'The state should fund free, universally accessible contraception for all women.', theme: 'Gender & Family', weight: 1.0, contextShort: 'Contraception is available at public clinics but access is uneven, especially in rural areas.', contextLong: 'Universal free contraception would reduce unwanted pregnancy and advance reproductive rights. Critics argue the cost is prohibitive and it undermines family planning decisions that belong to individuals.', axes: { economicLeft: 0.6, individualRights: 0.5, secularDemocracy: 0.4, traditionalAuthority: -0.4 } },
  { id: 'q237', text: 'Custody of children should default to shared parenting unless abuse is proven.', theme: 'Gender & Family', weight: 1.0, contextShort: 'Courts currently determine custody on a best-interests-of-the-child basis, often awarding primary custody to mothers.', contextLong: 'A default shared custody rule would recognise fathers\' parenting rights. Critics argue it could force children into unsafe situations and ignores the reality of unequal caregiving.', axes: { individualRights: 0.6, libertarian: 0.4, secularDemocracy: 0.2, traditionalAuthority: -0.2 } },
  { id: 'q238', text: 'Customary marriages should require the written consent of all parties to be legally recognised.', theme: 'Gender & Family', weight: 1.1, contextShort: 'Some customary marriages, particularly polygamous ones, occur without clear consent from all spouses.', contextLong: 'Written consent requirements would protect women from being entered into marriages without agreement. Critics argue it imposes administrative burdens on rural communities.', axes: { individualRights: 0.7, secularDemocracy: 0.5, traditionalAuthority: -0.6, stateAuthority: 0.3 } },
  { id: 'q239', text: 'Child support grants should be extended to fathers who are primary caregivers.', theme: 'Gender & Family', weight: 0.8, contextShort: 'Child support grants are typically paid to female caregivers; fathers as primary caregivers face administrative barriers.', contextLong: 'Extending access to all primary caregivers regardless of gender would reflect changing family structures. Critics say the barrier exists to prevent fraud.', axes: { individualRights: 0.5, economicLeft: 0.4, secularDemocracy: 0.3, transformation: 0.2 } },
  { id: 'q240', text: 'The state should provide free, professionally run after-school care for working parents.', theme: 'Gender & Family', weight: 0.9, contextShort: 'Many working mothers cannot afford after-school care, limiting their economic participation.', contextLong: 'State-funded after-school care would boost female workforce participation and child safety. Critics say it is unaffordable and encroaches on family responsibility.', axes: { economicLeft: 0.6, transformation: 0.4, secularDemocracy: 0.3, stateAuthority: 0.3 } },

  // ════════════════════════════════════════════
  // RELIGION & TRADITION (q069–q072, q141–q143, q164, q241–q244)
  // ════════════════════════════════════════════
  { id: 'q069', text: 'South Africa should be declared a secular state with no religious oaths in public office.', theme: 'Religion & Tradition', weight: 1.0, contextShort: 'Public officials may swear oaths with religious references.', contextLong: 'A fully secular state would separate religion from governance. Opponents see it as erasing South Africa\'s religious heritage.', axes: { secularDemocracy: 0.8, traditionalAuthority: -0.7, authoritarian: -0.3, libertarian: 0.4 } },
  { id: 'q070', text: 'Sharia law should be recognised in the South African legal system for Muslim personal matters.', theme: 'Religion & Tradition', weight: 1.1, contextShort: 'Muslim marriages are not fully recognised in South African law, creating legal vulnerabilities.', contextLong: 'Recognition would protect Muslim women and families but raises constitutional questions about equality and secularism.', axes: { traditionalAuthority: 0.6, secularDemocracy: -0.5, individualRights: 0.3, ubuntuCollectivism: 0.3 } },
  { id: 'q071', text: 'Traditional initiation schools should be strictly regulated by the state.', theme: 'Religion & Tradition', weight: 1.2, contextShort: 'Initiation schools have cultural significance but face criticism over deaths and unsafe practices.', contextLong: 'State regulation could save lives but could be seen as cultural interference. This tests the limit of state authority over cultural practices.', axes: { secularDemocracy: 0.6, stateAuthority: 0.5, traditionalAuthority: -0.6, libertarian: -0.3 } },
  { id: 'q072', text: 'Public holidays should reflect all major religious traditions equally.', theme: 'Religion & Tradition', weight: 0.7, contextShort: 'Public holidays currently favour Christian holidays.', contextLong: 'Adding holidays for Eid, Diwali, and other faiths would reflect SA\'s diversity but increase economic costs.', axes: { secularDemocracy: 0.4, traditionalAuthority: -0.3, ubuntuCollectivism: 0.5, westernAlignment: -0.2 } },
  { id: 'q141', text: 'The state should fund the construction of places of worship in new settlements.', theme: 'Religion & Tradition', weight: 0.6, contextShort: 'New RDP settlements often lack community facilities, including churches or mosques.', contextLong: 'State funding would support community cohesion and spiritual life, but blurs the line between church and state and favours organised religion.', axes: { traditionalAuthority: 0.5, secularDemocracy: -0.5, economicLeft: 0.3 } },
  { id: 'q142', text: 'Religious organisations should be required to disclose all foreign funding.', theme: 'Religion & Tradition', weight: 0.7, contextShort: 'Some religious groups receive substantial foreign donations, raising concerns about influence.', contextLong: 'Mandatory disclosure would increase transparency and prevent illicit flows. Critics say it targets religious groups unfairly and chills charitable giving.', axes: { secularDemocracy: 0.5, authoritarian: 0.3, westernAlignment: 0.2 } },
  { id: 'q143', text: 'The state should recognise and fund traditional courts as part of the judicial system.', theme: 'Religion & Tradition', weight: 1.0, contextShort: 'Traditional courts exist but their jurisdiction and funding are limited.', contextLong: 'Full integration would respect customary law and improve access to justice in rural areas. Critics say traditional courts often discriminate against women and lack formal legal training.', axes: { traditionalAuthority: 0.7, secularDemocracy: -0.6, constitutionalLiberalism: -0.3 } },
  { id: 'q164', text: 'Traditional initiation schools should be replaced by state-run rite-of-passage programmes.', theme: 'Religion & Tradition', weight: 0.8, contextShort: 'State programmes could standardise safety and curriculum while respecting cultural elements.', contextLong: 'This would drastically reduce deaths and injuries but could be seen as cultural erasure. It pits modernisation against tradition.', axes: { secularDemocracy: 0.7, traditionalAuthority: -0.6, stateAuthority: 0.5 } },
  { id: 'q241', text: 'Animal sacrifice as a religious or cultural practice should be legally protected.', theme: 'Religion & Tradition', weight: 0.8, contextShort: 'Animal sacrifice is practised in several South African religious and cultural traditions.', contextLong: 'Legal protection would respect cultural and religious freedom. Animal rights groups argue it constitutes cruelty.', axes: { traditionalAuthority: 0.6, libertarian: 0.3, secularDemocracy: -0.4, stateAuthority: -0.2 } },
  { id: 'q242', text: 'The school curriculum should include comparative religion as a compulsory subject.', theme: 'Religion & Tradition', weight: 0.8, contextShort: 'Religious education is offered in schools but often favours Christian perspectives.', contextLong: 'Comparative religion would build interfaith understanding. Critics argue it could conflict with parents\' religious beliefs.', axes: { secularDemocracy: 0.5, ubuntuCollectivism: 0.4, traditionalAuthority: -0.3, libertarian: -0.2 } },
  { id: 'q243', text: 'The state should not fund religious schools that refuse to admit students of other faiths.', theme: 'Religion & Tradition', weight: 1.0, contextShort: 'Faith-based schools receive state subsidies but can maintain admissions policies aligned with their faith.', contextLong: 'Defunding exclusionary schools would promote integration. Critics argue it violates religious freedom and the right to education in a community of choice.', axes: { secularDemocracy: 0.6, stateAuthority: 0.3, libertarian: -0.4, traditionalAuthority: -0.4 } },
  { id: 'q244', text: 'Sangomas and traditional healers should be licensed by the state and subject to malpractice law.', theme: 'Religion & Tradition', weight: 1.0, contextShort: 'Traditional healers are recognised but loosely regulated; harmful practices go largely unpunished.', contextLong: 'Licensing would protect patients and professionalise traditional healing. Critics say state licensing could destroy the spiritual basis of traditional healing.', axes: { stateAuthority: 0.5, secularDemocracy: 0.4, traditionalAuthority: -0.5, ubuntuCollectivism: 0.3 } },

  // ════════════════════════════════════════════
  // MEDIA & TECHNOLOGY (q073–q076, q144–q146, q245–q249)
  // ════════════════════════════════════════════
  { id: 'q073', text: 'Internet access should be a legal right, provided freely by the state.', theme: 'Media & Technology', weight: 0.9, contextShort: 'Internet access is not currently recognised as a constitutional right.', contextLong: 'Making internet access a right would bridge the digital divide but requires massive infrastructure investment.', axes: { economicLeft: 0.6, transformation: 0.5, libertarian: 0.3, stateAuthority: 0.3 } },
  { id: 'q074', text: 'Social media platforms should be liable for harmful content posted by users.', theme: 'Media & Technology', weight: 1.0, contextShort: 'Currently, platforms have limited liability under the Electronic Communications Act.', contextLong: 'Making platforms liable could reduce hate speech and misinformation but risks encouraging over-censorship.', axes: { authoritarian: 0.5, stateAuthority: 0.4, libertarian: -0.6, individualRights: -0.3 } },
  { id: 'q075', text: 'The state should actively regulate artificial intelligence development and deployment.', theme: 'Media & Technology', weight: 0.8, contextShort: 'South Africa lacks comprehensive AI regulation.', contextLong: 'Regulation could protect jobs and privacy but might stifle innovation.', axes: { stateAuthority: 0.5, authoritarian: 0.3, economicLeft: 0.3, libertarian: -0.4 } },
  { id: 'q076', text: 'The SABC should be funded by a mandatory household levy rather than advertising.', theme: 'Media & Technology', weight: 0.7, contextShort: 'The SABC struggles financially, relying on advertising and government bailouts.', contextLong: 'A levy would provide stable, independent funding for public broadcasting but is essentially a new tax.', axes: { economicLeft: 0.5, stateAuthority: 0.4, libertarian: -0.3, westernAlignment: -0.2 } },
  { id: 'q144', text: 'The government should be allowed to shut down social media during unrest.', theme: 'Media & Technology', weight: 0.9, contextShort: 'Internet shutdowns have been used in other countries to quell unrest, but SA has not implemented them.', contextLong: 'Shutting down social media could prevent the spread of incitement but also cuts off legitimate communication and news.', axes: { authoritarian: 0.6, libertarian: -0.6, stateAuthority: 0.5 } },
  { id: 'q145', text: 'All state databases should be built on open-source software.', theme: 'Media & Technology', weight: 0.5, contextShort: 'Government currently uses a mix of proprietary and open-source software.', contextLong: 'Open-source would reduce costs, improve security through transparency, and build local tech capacity. Critics say it requires specialised skills and may lack vendor support.', axes: { stateAuthority: -0.2, economicLeft: 0.3, libertarian: 0.4 } },
  { id: 'q146', text: 'South Africa should develop its own digital currency (CBDC).', theme: 'Media & Technology', weight: 0.7, contextShort: 'The SARB is exploring a central bank digital currency, but has not committed to launch.', contextLong: 'A digital rand could improve financial inclusion and payment efficiency. Critics warn it could undermine commercial banks and privacy.', axes: { stateAuthority: 0.5, economicLeft: 0.3, westernAlignment: -0.2 } },
  { id: 'q245', text: 'Tech companies should be required to share user data with the state for public health research.', theme: 'Media & Technology', weight: 0.8, contextShort: 'COVID-19 contact tracing highlighted the potential of mobile data for public health.', contextLong: 'Mandatory data sharing would enable evidence-based policy. Critics argue it is a massive privacy violation and surveillance risk.', axes: { authoritarian: 0.5, stateAuthority: 0.5, libertarian: -0.5, constitutionalLiberalism: -0.3 } },
  { id: 'q246', text: 'Online news platforms should require a journalism licence to operate.', theme: 'Media & Technology', weight: 0.8, contextShort: 'Traditional media is licensed but online news sites are not regulated in the same way.', contextLong: 'Licensing could impose quality and accountability standards. Critics say it would give the state power to silence online dissent.', axes: { authoritarian: 0.5, stateAuthority: 0.4, libertarian: -0.5, constitutionalLiberalism: -0.4 } },
  { id: 'q247', text: 'South Africa should develop a national AI strategy that prioritises local language models.', theme: 'Media & Technology', weight: 0.7, contextShort: 'AI tools are predominantly built for English and other major languages, marginalising African language speakers.', contextLong: 'A local AI strategy would promote linguistic sovereignty and create tech jobs. Critics say it is an inefficient use of resources.', axes: { transformation: 0.5, panAfrican: 0.4, economicLeft: 0.3, westernAlignment: -0.3 } },
  { id: 'q248', text: 'Children under 16 should be prohibited from holding social media accounts.', theme: 'Media & Technology', weight: 0.9, contextShort: 'Mental health concerns around social media and youth are growing globally.', contextLong: 'An age ban would protect children from online harm and addiction. Critics say it is unenforceable and removes a platform for youth civic engagement.', axes: { authoritarian: 0.4, stateAuthority: 0.3, libertarian: -0.4, individualRights: -0.3 } },
  { id: 'q249', text: 'The state should provide free tablets and connectivity to all school children.', theme: 'Media & Technology', weight: 1.0, contextShort: 'The digital divide is stark: many school children lack internet access and devices.', contextLong: 'Universal provision would equalise educational opportunity in the digital age. Critics question sustainability and whether infrastructure must come first.', axes: { economicLeft: 0.7, transformation: 0.5, stateAuthority: 0.3, westernAlignment: 0.2 } },

  // ════════════════════════════════════════════
  // LOCAL GOVERNMENT (q077–q079, q147–q149, q163, q250–q253)
  // ════════════════════════════════════════════
  { id: 'q077', text: 'Failing municipalities should be placed under provincial administration.', theme: 'Local Government', weight: 1.1, contextShort: 'Section 139 of the Constitution allows for provincial intervention in failing municipalities.', contextLong: 'Provincial administration can restore basic services but undermines local democracy.', axes: { stateAuthority: 0.5, constitutionalLiberalism: -0.4, stability: 0.4, transformation: -0.2 } },
  { id: 'q078', text: 'Ward committees should have binding decision-making power, not just advisory.', theme: 'Local Government', weight: 0.9, contextShort: 'Ward committees currently only advise councillors.', contextLong: 'Giving them binding power would deepen local democracy but could slow down decision-making.', axes: { libertarian: 0.5, constitutionalLiberalism: 0.4, stateAuthority: -0.3, transformation: 0.3 } },
  { id: 'q079', text: 'Ratepayer associations should be formally integrated into municipal governance structures.', theme: 'Local Government', weight: 0.8, contextShort: 'Ratepayer associations are voluntary groups that often challenge municipalities on service delivery.', contextLong: 'Formal integration could improve accountability but risks giving disproportionate power to wealthier communities.', axes: { economicRight: 0.4, constitutionalLiberalism: 0.3, transformation: -0.3, individualRights: 0.3 } },
  { id: 'q147', text: 'Municipalities should be allowed to raise their own taxes beyond property rates.', theme: 'Local Government', weight: 0.9, contextShort: 'Municipalities rely heavily on national transfers and property rates, limiting local fiscal autonomy.', contextLong: 'Greater taxing power would enable cities to raise their own revenue and be more responsive. Critics say it could lead to over-taxation and deepen inequality between rich and poor municipalities.', axes: { economicRight: 0.3, stateAuthority: -0.4, stability: 0.3 } },
  { id: 'q148', text: 'All municipal councillors should be full-time and well-paid to prevent corruption.', theme: 'Local Government', weight: 0.7, contextShort: 'Many councillors are part-time and poorly remunerated, which can make them vulnerable to bribes.', contextLong: 'Full-time, well-paid councillors would professionalise local government and reduce corruption. Critics say it would balloon municipal wage bills.', axes: { economicLeft: 0.3, stateAuthority: 0.4, stability: 0.2 } },
  { id: 'q149', text: 'Service delivery protests should be formally recognised as a form of petition.', theme: 'Local Government', weight: 0.8, contextShort: 'Service delivery protests are common, but they often turn violent and are treated as public order issues.', contextLong: 'Formal recognition would channel protests into official grievance mechanisms. Critics say it could legitimise disruption and undermine representative democracy.', axes: { libertarian: 0.5, transformation: 0.3, stateAuthority: -0.3 } },
  { id: 'q163', text: 'Informal traders should be exempt from all municipal by-laws.', theme: 'Local Government', weight: 0.7, contextShort: 'Informal traders often face harassment and fines for by-law violations like trading without a permit.', contextLong: 'Exempting them would acknowledge their role in the economy and reduce barriers. Critics say it would undermine formal businesses and create unregulated zones.', axes: { economicLeft: 0.3, libertarian: 0.5, stateAuthority: -0.3 } },
  { id: 'q250', text: 'Municipalities should be merged where populations fall below 50,000 to save costs.', theme: 'Local Government', weight: 0.8, contextShort: 'Many rural municipalities are too small to be financially viable, requiring large national transfers.', contextLong: 'Mergers would reduce administrative duplication. Critics argue they remove local governance from remote communities.', axes: { stability: 0.4, stateAuthority: 0.3, constitutionalLiberalism: -0.2, economicRight: 0.3 } },
  { id: 'q251', text: 'All municipal financial statements should be published online within 30 days of approval.', theme: 'Local Government', weight: 0.9, contextShort: 'Municipal financial disclosure is required but often delayed, making accountability difficult.', contextLong: 'Rapid online disclosure would enable civil society and media to monitor spending. Critics say it is administratively demanding for smaller municipalities.', axes: { constitutionalLiberalism: 0.5, libertarian: 0.4, stateAuthority: -0.2, stability: 0.3 } },
  { id: 'q252', text: 'Community members should be able to petition for a no-confidence vote in their ward councillor.', theme: 'Local Government', weight: 0.9, contextShort: 'Ward councillors face no direct recall mechanism between elections.', contextLong: 'A petition-based no-confidence mechanism would deepen local accountability. Critics warn it could be weaponised by party factions.', axes: { libertarian: 0.5, constitutionalLiberalism: 0.4, stateAuthority: -0.3, stability: -0.2 } },
  { id: 'q253', text: 'Land use planning should be removed from municipal control and centralised at provincial level.', theme: 'Local Government', weight: 0.8, contextShort: 'Municipal land use decisions have been criticised for being captured by local developers.', contextLong: 'Centralisation would reduce corruption and ensure consistent urban planning. Critics argue it removes local context from planning decisions.', axes: { stateAuthority: 0.5, stability: 0.3, constitutionalLiberalism: -0.3, economicRight: -0.2 } },

  // ════════════════════════════════════════════
  // LABOUR (q080–q083, q150–q152, q254–q257)
  // ════════════════════════════════════════════
  { id: 'q080', text: 'The right to strike should be protected without limitation for essential services.', theme: 'Labour', weight: 1.2, contextShort: 'Essential service workers have limited or no right to strike in South Africa.', contextLong: 'Removing limits would strengthen labour but could endanger lives if healthcare, power, or water services are disrupted.', axes: { economicLeft: 0.6, libertarian: 0.4, stateAuthority: -0.3, stability: -0.5 } },
  { id: 'q081', text: 'Gig economy workers (Uber, Bolt) should be classified as employees with full benefits.', theme: 'Labour', weight: 1.0, contextShort: 'Gig workers are currently independent contractors, not employees.', contextLong: 'Reclassification would provide job security and benefits but could increase costs and reduce flexibility of the gig economy model.', axes: { economicLeft: 0.7, transformation: 0.5, ubuntuCollectivism: 0.4, economicRight: -0.5 } },
  { id: 'q082', text: 'Closed shop agreements (mandatory union membership) should be banned.', theme: 'Labour', weight: 0.9, contextShort: 'Closed shop agreements require all workers in a workplace to join a union.', contextLong: 'Banning them would protect individual worker choice but could weaken collective bargaining power.', axes: { individualRights: 0.6, economicRight: 0.4, ubuntuCollectivism: -0.5, economicLeft: -0.3 } },
  { id: 'q083', text: 'The Employment Equity Act should be strengthened with stricter racial and gender targets.', theme: 'Labour', weight: 1.1, contextShort: 'The Employment Equity Act already requires affirmative action reporting.', contextLong: 'Stricter targets would accelerate transformation but could be seen as rigid quotas that undermine merit.', axes: { racialRedress: 0.7, transformation: 0.6, economicLeft: 0.4, nonRacialism: -0.5 } },
  { id: 'q150', text: 'Workers should have representation on company boards.', theme: 'Labour', weight: 1.0, contextShort: 'German-style co-determination gives workers seats on boards, a model proposed by some unions.', contextLong: 'Worker representation could align corporate decisions with employee interests and reduce inequality. Critics say it would politicise boardrooms and slow decision-making.', axes: { economicLeft: 0.6, transformation: 0.5, ubuntuCollectivism: 0.5 } },
  { id: 'q151', text: 'The four-day work week should be piloted in the public sector.', theme: 'Labour', weight: 0.8, contextShort: 'Some countries are experimenting with a four-day work week with no loss of pay.', contextLong: 'A pilot could improve work-life balance and productivity. Critics worry about service delivery gaps and cost.', axes: { economicLeft: 0.4, transformation: 0.3, libertarian: 0.3 } },
  { id: 'q152', text: 'Trade unions should be allowed to invest in companies they negotiate with.', theme: 'Labour', weight: 0.7, contextShort: 'Unions currently may invest pension funds in companies, but direct investment in bargaining employers is rare.', contextLong: 'This could give unions more influence over company policy, but creates conflicts of interest.', axes: { economicLeft: 0.5, stateAuthority: -0.3, authoritarian: 0.2 } },
  { id: 'q254', text: 'Domestic workers should be entitled to all the same benefits as other employees, including UIF and pension.', theme: 'Labour', weight: 1.1, contextShort: 'Domestic workers have some protections but compliance is low and enforcement is weak.', contextLong: 'Full benefits would recognise domestic work\'s social value and protect a predominantly black, female workforce. Critics say it would drive employment of domestic workers underground.', axes: { economicLeft: 0.7, transformation: 0.5, racialRedress: 0.5, economicRight: -0.4 } },
  { id: 'q255', text: 'Employers should be legally required to hire a fixed percentage of youth in all new positions.', theme: 'Labour', weight: 1.0, contextShort: 'Youth unemployment exceeds 60% in South Africa — among the highest in the world.', contextLong: 'A youth hiring quota would forcibly address the crisis. Critics argue it reduces employer freedom and may result in lower-quality hiring.', axes: { stateAuthority: 0.5, economicLeft: 0.5, transformation: 0.4, economicRight: -0.5 } },
  { id: 'q256', text: 'Collective bargaining should extend to workers in the informal economy.', theme: 'Labour', weight: 1.0, contextShort: 'Collective bargaining rights apply to formal employees; informal workers are excluded.', contextLong: 'Extending bargaining rights would give the informal sector a voice. Critics question whether bargaining is practical without an employer-employee relationship.', axes: { economicLeft: 0.7, transformation: 0.5, ubuntuCollectivism: 0.5, economicRight: -0.3 } },
  { id: 'q257', text: 'Employers who retrench more than 50 workers should be required to fund retraining programmes.', theme: 'Labour', weight: 1.0, contextShort: 'Mass retrenchments often leave workers with no alternative skills or income.', contextLong: 'Mandatory retraining funding would cushion job losses and build human capital. Critics say it would deter investment and make SA an unattractive location for business.', axes: { economicLeft: 0.6, transformation: 0.4, stateAuthority: 0.4, economicRight: -0.5 } },

  // ════════════════════════════════════════════
  // CRIME & REHABILITATION (q084–q087, q153–q155, q258–q260)
  // ════════════════════════════════════════════
  { id: 'q084', text: 'Life imprisonment should mean life without the possibility of parole.', theme: 'Crime & Rehabilitation', weight: 1.0, contextShort: 'Life sentences in South Africa allow for parole consideration after 25 years.', contextLong: 'Ending parole for life sentences would satisfy demands for harsher punishment but eliminates rehabilitation as a goal.', axes: { authoritarian: 0.7, libertarian: -0.6, constitutionalLiberalism: -0.4, stateAuthority: 0.4 } },
  { id: 'q085', text: 'Restorative justice should be the primary approach for non-violent crimes.', theme: 'Crime & Rehabilitation', weight: 0.8, contextShort: 'Restorative justice focuses on repairing harm between victim, offender, and community.', contextLong: 'It reduces recidivism and prison overcrowding but requires willing participation.', axes: { libertarian: 0.5, ubuntuCollectivism: 0.6, individualRights: 0.4, authoritarian: -0.4 } },
  { id: 'q086', text: 'Private prisons should be banned.', theme: 'Crime & Rehabilitation', weight: 0.9, contextShort: 'Two private prisons operate in SA under contract with the Department of Correctional Services.', contextLong: 'Opponents argue profit motives lead to corner-cutting. Supporters say they relieve state capacity.', axes: { economicLeft: 0.5, stateAuthority: 0.4, libertarian: -0.3 } },
  { id: 'q087', text: 'All prisoners should have the right to vote.', theme: 'Crime & Rehabilitation', weight: 0.9, contextShort: 'The Constitutional Court has ruled that prisoners have the right to vote, but practical barriers remain.', contextLong: 'Ensuring prisoner voting upholds constitutional rights and aids rehabilitation. Critics argue it undermines the social contract.', axes: { libertarian: 0.4, individualRights: 0.5, constitutionalLiberalism: 0.4, authoritarian: -0.3 } },
  { id: 'q153', text: 'Prison labour should be expanded and inmates paid minimum wage.', theme: 'Crime & Rehabilitation', weight: 0.8, contextShort: 'Inmates currently perform work but are paid far below minimum wage.', contextLong: 'Paying minimum wage would teach skills and provide income for victims\' compensation. Critics say it undercuts free labour and could lead to exploitation.', axes: { economicLeft: 0.5, libertarian: 0.3, authoritarian: -0.2 } },
  { id: 'q154', text: 'All criminal records for non-violent offences should be expunged after 10 years.', theme: 'Crime & Rehabilitation', weight: 0.9, contextShort: 'Expungement is possible but requires a lengthy court process.', contextLong: 'Automatic expungement would help ex-offenders reintegrate and find employment. Critics say it undermines the deterrent effect.', axes: { libertarian: 0.6, authoritarian: -0.4, individualRights: 0.5 } },
  { id: 'q155', text: 'Illegal drug use should be treated as a public health issue, not a criminal one.', theme: 'Crime & Rehabilitation', weight: 1.2, contextShort: 'Portugal-style decriminalisation has been debated, but SA maintains criminal penalties for drug use.', contextLong: 'A public health approach would reduce incarceration and focus on treatment. Critics say it could normalise drug use and increase addiction.', axes: { libertarian: 0.7, authoritarian: -0.6, secularDemocracy: 0.3 } },
  { id: 'q258', text: 'The age of criminal responsibility should be raised from 10 to 14 years.', theme: 'Crime & Rehabilitation', weight: 1.0, contextShort: 'Children as young as 10 can currently be prosecuted in South Africa.', contextLong: 'Raising the age aligns with child development research and international norms. Critics argue some children commit very serious crimes.', axes: { libertarian: 0.5, constitutionalLiberalism: 0.4, individualRights: 0.4, authoritarian: -0.5 } },
  { id: 'q259', text: 'Victims of crime should have formal standing to participate in sentencing proceedings.', theme: 'Crime & Rehabilitation', weight: 0.9, contextShort: 'Victims currently have limited formal rights in sentencing; victim impact statements are discretionary.', contextLong: 'Formal victim participation would make sentences more responsive to harm caused. Critics worry it could introduce punitive bias and overwhelm the justice system.', axes: { individualRights: 0.5, authoritarian: 0.3, constitutionalLiberalism: 0.2, libertarian: -0.2 } },
  { id: 'q260', text: 'Overcrowded prisons should be addressed through mass release of non-violent offenders.', theme: 'Crime & Rehabilitation', weight: 1.0, contextShort: 'South African prisons operate at over 150% capacity, violating constitutional rights.', contextLong: 'Mass release of non-violent offenders would address the crisis but may face public backlash. Critics argue it rewards criminal behaviour.', axes: { libertarian: 0.6, constitutionalLiberalism: 0.5, authoritarian: -0.5, stateAuthority: -0.3 } },

  // ════════════════════════════════════════════
  // HEALTH & AUTONOMY (q088–q091, q156–q158, q261–q263)
  // ════════════════════════════════════════════
  { id: 'q088', text: 'Euthanasia should be legalised for terminally ill patients.', theme: 'Health & Autonomy', weight: 1.0, contextShort: 'The SA Law Reform Commission has recommended legalising assisted dying under strict conditions.', contextLong: 'Current law treats assisted suicide as murder. The debate involves personal autonomy, medical ethics, and religious beliefs.', axes: { libertarian: 0.7, individualRights: 0.6, traditionalAuthority: -0.5, secularDemocracy: 0.3 } },
  { id: 'q089', text: 'Organ donation should be opt-out rather than opt-in.', theme: 'Health & Autonomy', weight: 0.8, contextShort: 'South Africa has an opt-in system with very low donor rates.', contextLong: 'An opt-out system would significantly increase available organs for transplant but raises bodily autonomy concerns.', axes: { authoritarian: 0.3, stateAuthority: 0.3, individualRights: -0.4, libertarian: -0.3 } },
  { id: 'q090', text: 'Mandatory vaccination for all eligible adults during pandemics is justified.', theme: 'Health & Autonomy', weight: 1.1, contextShort: 'COVID-19 vaccination was voluntary in South Africa.', contextLong: 'Mandatory vaccination during pandemics protects public health but can infringe on bodily autonomy.', axes: { authoritarian: 0.6, stateAuthority: 0.5, libertarian: -0.6, individualRights: -0.4 } },
  { id: 'q091', text: 'Psychedelic-assisted therapy should be legalised for mental health treatment.', theme: 'Health & Autonomy', weight: 0.7, contextShort: 'Psychedelics remain illegal in South Africa despite growing global evidence of therapeutic benefits.', contextLong: 'Legalisation for therapy could revolutionise treatment for depression and PTSD but requires careful regulation.', axes: { libertarian: 0.6, secularDemocracy: 0.4, individualRights: 0.5, traditionalAuthority: -0.3 } },
  { id: 'q156', text: 'Surrogacy should be legal for single people and same-sex couples.', theme: 'Health & Autonomy', weight: 0.9, contextShort: 'Current law allows surrogacy but some requirements make it difficult for single and same-sex parents.', contextLong: 'Expanding access would uphold equality rights and provide family options for diverse households. Critics raise concerns about child welfare and commercialisation.', axes: { individualRights: 0.6, traditionalAuthority: -0.5, secularDemocracy: 0.4 } },
  { id: 'q157', text: 'The state should fund gender-affirming surgery for transgender individuals.', theme: 'Health & Autonomy', weight: 1.0, contextShort: 'Gender-affirming surgery is available in the public sector but with long waiting lists and limited coverage.', contextLong: 'Full funding would affirm transgender rights and improve mental health. Critics question the use of public funds for non-life-threatening procedures.', axes: { libertarian: 0.6, individualRights: 0.7, traditionalAuthority: -0.5 } },
  { id: 'q158', text: 'All pregnant women should be tested for HIV unless they explicitly opt out.', theme: 'Health & Autonomy', weight: 0.8, contextShort: 'South Africa has an opt-out testing policy for HIV in antenatal care.', contextLong: 'Opt-out testing increases detection and prevents mother-to-child transmission. Critics say it can feel coercive and must be accompanied by strong counselling.', axes: { authoritarian: 0.3, stateAuthority: 0.4, individualRights: -0.2 } },
  { id: 'q261', text: 'HIV status should be a protected disclosure — sharing it without consent should be a criminal offence.', theme: 'Health & Autonomy', weight: 1.0, contextShort: 'HIV disclosure without consent occurs and causes significant harm.', contextLong: 'Criminal protection of HIV status would combat stigma and protect privacy. Critics argue it could conflict with partner notification rights in public health.', axes: { individualRights: 0.6, libertarian: 0.5, stateAuthority: -0.2, authoritarian: -0.3 } },
  { id: 'q262', text: 'Medical aid schemes should be prohibited from excluding pre-existing conditions.', theme: 'Health & Autonomy', weight: 1.1, contextShort: 'Medical aids may impose waiting periods for pre-existing conditions, leaving sick people without cover.', contextLong: 'Prohibiting exclusions would protect the chronically ill but increase premiums. Critics say it makes insurance financially unviable and contradicts actuarial principles.', axes: { economicLeft: 0.6, transformation: 0.4, stateAuthority: 0.4, economicRight: -0.5 } },
  { id: 'q263', text: 'Assisted suicide should be legal only when approved by a panel of three doctors.', theme: 'Health & Autonomy', weight: 0.9, contextShort: 'Assisted dying legislation is under development following a 2023 high court ruling.', contextLong: 'A panel requirement would balance patient autonomy with protection against premature death. Critics say it is bureaucratic and could deny dying patients a timely choice.', axes: { libertarian: 0.4, individualRights: 0.5, stateAuthority: 0.2, traditionalAuthority: -0.3 } },

  // ════════════════════════════════════════════
  // CONSTITUTIONAL LAW (q092–q095, q159–q161, q264–q265)
  // ════════════════════════════════════════════
  { id: 'q092', text: 'The Constitution should be amended to allow expropriation without compensation.', theme: 'Constitutional Law', weight: 1.4, contextShort: 'Section 25 requires just and equitable compensation for expropriation.', contextLong: 'Amendment would explicitly allow nil compensation in certain circumstances. This is a core EFF and ANC resolution; opposed by the DA and FF+. This is one of the most consequential constitutional questions in SA today.', axes: { transformation: 0.9, racialRedress: 0.8, economicLeft: 0.6, constitutionalLiberalism: -0.8, westernAlignment: -0.5 } },
  { id: 'q093', text: 'The Constitutional Court should have the power to strike down constitutional amendments.', theme: 'Constitutional Law', weight: 1.1, contextShort: 'The Constitutional Court can review amendments for procedural flaws but not substantive unconstitutionality.', contextLong: 'Giving the Court substantive review over amendments would protect the Constitution\'s core values but could make it difficult to amend. This tests judicial supremacy vs. parliamentary sovereignty.', axes: { constitutionalLiberalism: 0.7, stateAuthority: -0.5, stability: 0.5, transformation: -0.3 } },
  { id: 'q094', text: 'South Africa should introduce jury trials for serious criminal cases.', theme: 'Constitutional Law', weight: 0.8, contextShort: 'Jury trials were abolished in 1969 and not reintroduced post-apartheid.', contextLong: 'Juries would democratise justice and involve citizens directly but could be vulnerable to bias in a deeply divided society.', axes: { libertarian: 0.5, constitutionalLiberalism: 0.4, stateAuthority: -0.3, authoritarian: -0.3 } },
  { id: 'q095', text: 'The amendment threshold for the Bill of Rights should be raised to 75%.', theme: 'Constitutional Law', weight: 1.0, contextShort: 'Currently, the Bill of Rights can be amended with a two-thirds majority in the National Assembly.', contextLong: 'A higher threshold would protect fundamental rights from political majorities but could entrench the constitutional text. This tests your preference for constitutional rigidity vs. flexibility.', axes: { constitutionalLiberalism: 0.6, stability: 0.5, transformation: -0.4, stateAuthority: -0.3 } },
  { id: 'q159', text: 'The Constitution should guarantee a right to housing within a specific timeframe.', theme: 'Constitutional Law', weight: 1.1, contextShort: 'Section 26 provides a right to adequate housing, but it is progressively realisable.', contextLong: 'A binding timeframe would force the state to accelerate housing delivery. Critics say it is unrealistic and could lead to court orders that the state cannot fulfil.', axes: { transformation: 0.6, economicLeft: 0.5, constitutionalLiberalism: -0.2 } },
  { id: 'q160', text: 'The judiciary should be able to review the constitutionality of constitutional amendments.', theme: 'Constitutional Law', weight: 1.2, contextShort: 'The Constitutional Court can review amendments for procedural flaws but not for substantive constitutionality.', contextLong: 'Substantive review would protect the core values of the Constitution from being amended away. Opponents argue it would give judges a veto over the elected branches.', axes: { constitutionalLiberalism: 0.8, stateAuthority: -0.5, transformation: -0.4 } },
  { id: 'q161', text: 'The state should be required to provide legal representation in all civil cases, not just criminal.', theme: 'Constitutional Law', weight: 0.9, contextShort: 'Legal aid is mostly available for criminal cases, leaving many civil litigants without representation.', contextLong: 'Expanding legal aid would improve access to justice but would be enormously costly.', axes: { economicLeft: 0.5, individualRights: 0.6, constitutionalLiberalism: 0.4 } },
  { id: 'q264', text: 'Judges of the Constitutional Court should be elected by the public, not appointed by a commission.', theme: 'Constitutional Law', weight: 1.0, contextShort: 'Judges are currently appointed via the Judicial Service Commission, shielding them from popular pressure.', contextLong: 'Public election would democratise the judiciary. Critics argue it would expose judges to political campaigns and undermine judicial independence.', axes: { libertarian: 0.3, stateAuthority: 0.3, constitutionalLiberalism: -0.5, authoritarian: 0.3 } },
  { id: 'q265', text: 'The Constitution should include explicit rights for future generations regarding environmental protection.', theme: 'Constitutional Law', weight: 1.0, contextShort: 'Section 24 provides environmental rights but does not explicitly protect future generations.', contextLong: 'Intergenerational rights would create legal standing for environmental protection across decades. Critics argue they are unenforceable and would create litigation uncertainty.', axes: { constitutionalLiberalism: 0.4, economicLeft: 0.3, westernAlignment: 0.4, stateAuthority: 0.2 } }

];